-- ============================================================
-- V1.58__seed_qa_art_collection.sql
-- 闲鱼平台 AI 客服学习知识库种子数据
-- 一级分类：艺术品收藏 (art_collection)
-- 二级分类：5个，每个30条，共150条Q&A
-- ============================================================
--
-- 二级分类清单：
--   1. art_calligraphy  - 字画书法（30条）
--   2. art_stamp_coin   - 邮票钱币（30条）
--   3. art_antique      - 古董收藏（30条）
--   4. art_trendy       - 潮玩手办（30条）
--   5. art_memorabilia  - 纪念品  （30条）
--
-- 涵盖场景：
--   真假辨别、年代鉴定、品相评估、来源追溯、证书核验、
--   破损处理、原装判断、市场定价、收藏价值、保养维护
--
-- 技术说明：
--   - content_hash 由 MD5(question + answer) 生成，配合 UNIQUE KEY 保证幂等
--   - vector_indexed=1 表示已建立向量索引
--   - score 范围 70-95，体现问答质量分级
--   - source_type='seed' 标识种子数据
--   - learn_batch_id='seed-v1.58' 标识本批次
--   - 通过 JOIN ai_cs_kb_category 关联分类ID（parent_id IS NOT NULL 确保是二级分类）
--   - 单引号在内容中已用 '' 转义
--
-- 幂等性：本脚本可重复执行，因 content_hash + deleted 唯一约束，
--        重复执行时相同 hash 的记录会被忽略（需配合 INSERT IGNORE 使用）。
--        当前使用 INSERT INTO ... SELECT 形式，重复执行会因唯一键冲突报错，
--        故应在 Flyway 版本控制下仅执行一次。
-- ============================================================


-- ============================================================
-- 1. 字画书法 (art_calligraphy) - 30条
-- ============================================================
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.58', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'art_calligraphy' AS code, '这幅齐白石画虾是真的吗？怎么辨别真假？' AS question,
         '您好，齐白石虾图的鉴别主要看几个方面：一是笔墨韵味，真迹用笔老辣干脆，虾须一气呵成有弹性，仿品线条往往犹豫发飘；二是墨色层次，齐老画虾墨分五色，浓淡过渡自然，虾身透明感强；三是落款印章，齐白石不同时期用印有讲究，85岁后多用"白石"二字款，印泥颜色也有时代特征。建议您多拍几张高清细节图发给我，特别是虾须、虾钳、落款和印章部位。闲鱼上字画水比较深，没有实物上手很难百分百断定，但我们可以一起分析判断。您方便发几张细节图给我看看吗？期待您的回复。' AS answer,
         '真假辨别,齐白石,字画,虾图' AS tags, '齐白石虾图真假鉴别要点' AS source_summary, 92 AS score
  UNION ALL SELECT 'art_calligraphy', '这幅字画是什么年代的？怎么看是民国还是清代的？',
         '您好，判断字画年代主要从几个维度入手：第一看纸张，清代多用手工宣纸和皮纸，纤维长有帘纹，民国时期机制纸开始流行；第二看墨色，老字画墨色会随时间氧化泛出灰白光泽，新墨则黑亮刺眼；第三看印章和印泥，老印泥颜色沉稳有渗透感，新印泥鲜艳浮于表面；第四看装裱工艺，不同年代裱工手法和用料有别。从您描述的包浆和纸色来看，民国时期的可能性较大。建议您拍一下落款、纸张边缘和印章的高清图，我可以帮您更准确地分析。另外如果有落款年份或作者信息也能辅助判断，您方便发来看看吗？',
         '年代鉴定,民国,清代,纸张', '字画年代判断的多维度方法', 88
  UNION ALL SELECT 'art_calligraphy', '老字画有虫蛀了还能买吗？品相对价值影响多大？',
         '您好，老字画有虫蛀是比较常见的情况，毕竟纸本绢本历经几十年上百年难免有损伤。虫蛀对价值的影响主要看位置和程度：如果蛀在画面主体，比如人物面部、山水主景处，影响较大，可能贬值30%到50%；如果蛀在边角空白处，影响较小，贬值10%到20%。买虫蛀字画建议先评估修复成本，专业裱画师可以做"补画"修复，但费用不低。另外买到后要第一时间做灭虫处理，防止虫蛀继续蔓延。您可以发张虫蛀部位的清晰照片给我，我帮您评估一下影响程度和修复可行性，看看价格是否合理。',
         '品相,虫蛀,修复,价值评估', '虫蛀字画的品相影响与修复建议', 85
  UNION ALL SELECT 'art_calligraphy', '家里传下来的字画没有证书没有发票，好卖吗？',
         '您好，家传字画没有证书在闲鱼上其实很常见，很多老货都是这种情况。没有证书不代表不能卖，关键是要把"传承有序"这个故事讲好。建议您在商品描述里写清楚以下几点：一是家传来源，比如爷爷那一辈传下来的，简要说一下来历；二是字画的可见信息，包括作者、落款内容、印章文字；三是多角度高清图片，整体、局部、落款、印章、纸张纹理都要拍；四是诚实说明品相和瑕疵。买家最看重的是真实性和透明度。定价方面，没有证书的名家作品通常比有证书的便宜两到三成，但如果是真迹依然有收藏价值。您方便告诉我作者是谁吗？',
         '来源,家传,无证书,销售技巧', '家传无证书字画的销售策略', 87
  UNION ALL SELECT 'art_calligraphy', '字画的证书怎么看真假？哪种证书比较靠谱？',
         '您好，字画证书的鉴别主要看几个方面：一看发证机构，正规机构如省级以上美协、书画院、知名拍卖行的证书比较有参考价值，野鸡机构花钱就能办的证书意义不大；二看证书编号，正规证书都有唯一编号，可以联系发证机构核实；三看钢印和骑缝章，真证书钢印清晰有立体感，假证书多为印刷图案；四看纸张和印刷工艺，假证书常有套色不准、纸张廉价的问题。不过要提醒您，字画圈证书的含金量参差不齐，有些机构认证流于形式，最关键的还是要看作品本身的笔墨功力和作者风格。建议证书作为参考，重点回归作品本身。您能把证书和作品都发来看看吗？',
         '证书,鉴定,真伪,机构', '字画证书真伪鉴别与可信度判断', 86
  UNION ALL SELECT 'art_calligraphy', '字画有折痕和破损，还值钱吗？',
         '您好，字画有折痕和破损对价值确实有影响，但具体多大要看破损程度和位置。折痕方面，轻微折痕通过重新装裱可以恢复大部分品相，影响不大；但如果折痕已经断裂伤及画面，就比较麻烦了。破损方面，画面主体部位的破损影响最大，可能贬值40%以上；边角小破损影响相对小。建议您评估几个方面：一是作品本身的艺术价值和作者知名度，名家精品即使有残依然保值；二是修复成本和修复后效果；三是当前价格是否已经反映了品相问题。如果价格合适且有修复空间，是可以考虑入手的。您发张破损部位的图给我，我帮您看看修复可行性。',
         '品相,破损,折痕,修复', '字画折痕破损的价值影响评估', 83
  UNION ALL SELECT 'art_calligraphy', '这幅字画是原装老裱还是后来重新装裱的？',
         '您好，判断字画是原装老裱还是新裱，主要看几个方面：一是裱工的包浆，老裱的裱边、天杆地杆会有自然老化痕迹，颜色沉稳有岁月感；二是裱纸材质，不同年代用的裱纸、绫绢纹样有时代特征；三是装裱工艺，老裱多用手工传统工艺，新裱多为机器裱，手感和平整度有区别；四是镶料颜色，老裱的绫绢颜色经过岁月会泛旧，新裱颜色鲜亮。原装老裱对字画价值有加持作用，尤其是名家作品的原装裱更能证明传承。不过也要注意，有些做旧的假老裱，需要仔细辨别。您方便拍几张裱边、天杆地杆和背面裱工的细节图给我看看吗？',
         '原装,装裱,老裱,品相', '原装老裱与新裱的辨别方法', 84
  UNION ALL SELECT 'art_calligraphy', '当代名家字画现在市场价大概多少？怎么定价合理？',
         '您好，当代名家字画的定价比较复杂，受多个因素影响：一是作者的知名度和地位，美协会员、画院专业画师、院校教授的作品价格较高；二是作品的尺寸和题材，大幅工整作品比小品贵，代表性题材比普通题材贵；三是创作年代和精品程度，画家巅峰期的精品价格高；四是有无权威著录或展览记录。建议您参考几个渠道来定价：一是查阅雅昌艺术网等平台的拍卖记录；二是看同类作品在画廊的标价；三是参考闲鱼和微拍堂上同类作品的成交价。定价时留一定议价空间。您能告诉我作者是谁、尺寸多大吗？我帮您查查行情。',
         '市场价,定价,当代名家,行情', '当代名家字画定价参考因素', 89
  UNION ALL SELECT 'art_calligraphy', '中青年画家的作品有收藏价值吗？值得入手吗？',
         '您好，中青年画家的作品确实是一个值得关注的收藏方向，但需要慧眼识珠。收藏中青年画家作品的好处是价格相对亲民，未来升值空间大；风险是画家的艺术成就和市场认可度还没定型。建议您从几个方面判断：一看学术背景，是否有专业美院学历、是否在重要展览中入选获奖；二看个人风格，是否有鲜明的艺术语言而非单纯模仿；三看市场表现，是否有画廊代理、是否有稳定的藏家群体；四看创作态度，是职业画家还是业余爱好。建议以"自己喜欢"为第一原则，在财力允许范围内入手，不要抱着暴富心态。您有看中的具体画家吗？',
         '收藏价值,中青年画家,投资,潜力', '中青年画家作品的收藏价值判断', 86
  UNION ALL SELECT 'art_calligraphy', '字画怎么保养？怕潮湿吗？',
         '您好，字画保养非常重要，保养不当会严重影响品相和价值。字画最怕潮湿，南方梅雨季节尤其要注意。保养要点如下：一是存放环境要保持干燥通风，相对湿度控制在50%到60%之间，可放干燥剂但不要直接接触画心；二是避免阳光直射，紫外线会使纸绢老化变脆、墨色褪色；三是防虫防鼠，存放处可放樟脑或防虫剂，定期检查有无虫蛀；四是取放时要戴棉质手套，避免手汗污染；五是卷放时不要卷太紧，避免折痕；六是悬挂展示要避免厨房油烟和空调直吹。建议每半年拿出来通风检查一次。您是南方还是北方的？我给您更有针对性的建议。',
         '保养,防潮,存放,维护', '字画防潮防虫保养要点', 88
  UNION ALL SELECT 'art_calligraphy', '这幅启功书法是真的吗？启功的字怎么鉴定？',
         '您好，启功先生的书法在市场上仿品非常多，鉴定需要仔细。启功书法的鉴别要点：一是结体特征，启功字结体修长偏瘦，中宫收紧而四面辐射，有独特的"启体"风格；二是用笔特点，起笔收笔干净利落，线条清瘦挺拔，行笔有节奏感；三是题款习惯，启功题款多写"启功"二字，偶写"元白"，字体偏小而精到；四是用印规律，常用印有"启功""元白""坚净居"等，印泥颜色有个人偏好。仿品常见问题是用笔软弱无力、结体松散、题款发飘。建议您多拍几张高清细节图，特别是笔画的起收笔和转折处，我帮您仔细看看。',
         '真假辨别,启功,书法,鉴定', '启功书法真伪鉴定要点', 90
  UNION ALL SELECT 'art_calligraphy', '字画尺寸大小和价格有关系吗？是不是越大越值钱？',
         '您好，字画尺寸和价格确实有关系，但不是简单的"越大越值钱"。字画定价通常按平尺计算，但不同尺寸的每平尺单价会有差异：一般中等尺寸（如四尺整纸、四尺对开）的每平尺单价最高，因为这是画家最顺手创作的尺寸，精品率高；太大或太小的尺寸单价可能略低。另外影响价格的因素还有：一是题材，工笔通常比写意贵，人物比花鸟贵；二是精品程度，同一画家不同作品的水平差异很大；三是品相和装裱；四是是否有著录。所以不能只看尺寸，要综合评估。您能告诉我画的具体尺寸和作者吗？我帮您评估一下合理价位。',
         '尺寸,定价,平尺,市场价', '字画尺寸与价格的关系分析', 82
  UNION ALL SELECT 'art_calligraphy', '地摊上买的字画能是真迹吗？怎么看仿品？',
         '您好，地摊上的字画要特别谨慎，绝大多数是印刷品或低仿品。常见的仿品类型有几种：一是高仿印刷品，用高科技印刷手段复制名家作品，远看像真迹，近看能看到网点；二是手工临摹品，画工仿制但笔墨功力远不及原作者；三是半印半画，先印刷轮廓再手工填色。鉴别方法：一是看笔墨，真迹有毛笔的书写质感和墨色变化，印刷品则平面呆板；二是看纸张，老字画纸张有自然老化，新仿纸张做旧痕迹不自然；三是看细节，印刷品放大后能看到规律的网点。建议新手不要在地摊上买高价字画，风险太大。您发张图我帮您看看是印刷还是手绘的。',
         '仿品,地摊,印刷品,真假辨别', '地摊字画仿品识别方法', 80
  UNION ALL SELECT 'art_calligraphy', '想投资字画，有什么建议？新手怎么入门？',
         '您好，字画投资是个需要积累的领域，给新手几点建议：一是先学后买，多看展览、画册、拍卖预展，培养眼力，不要急着出手；二是量力而行，用闲钱收藏，不要借钱投资，字画流动性不如股票；三是聚焦领域，不要什么都买，选定一个方向深入，比如专收某位画家或某类题材；四是买精品不买普品，宁可花同样的钱买一幅小品精品，也不要买一幅大尺寸应酬之作；五是通过正规渠道购买，选择有信誉的画廊、拍卖行或可追溯的藏家；六是保留购买凭证和传承记录。字画收藏最大的回报往往来自长期持有。您有特别感兴趣的方向吗？',
         '投资,入门,新手建议,收藏', '字画投资新手入门指南', 91
  UNION ALL SELECT 'art_calligraphy', '字画的老裱和新裱有什么区别？哪种好？',
         '您好，字画的老裱和新裱各有特点，不能简单说哪种好。老裱的优势在于：一是历史感强，能佐证字画的年代和传承；二是传统手工工艺，裱工精细耐久；但老裱的劣势是可能老化脱裱需要重裱。新裱的优势在于：一是保护字画，重新装裱可以修复老裱的损伤；二是美观度好，新裱的绫绢颜色鲜亮；劣势是失去了原裱的历史信息。如果是名家精品且有原装老裱，建议保留原裱不要轻易重裱，因为原裱本身就是价值的一部分。如果老裱已经严重老化影响保存，则建议找靠谱的裱画师重新装裱。您这幅字画的裱工状况怎么样？',
         '装裱,老裱,新裱,品相', '老裱与新裱的区别与选择建议', 83
  UNION ALL SELECT 'art_calligraphy', '字画上的印章怎么鉴别？印章能看出真假吗？',
         '您好，印章是字画鉴定的重要依据之一。鉴别印章主要看几个方面：一是印文内容，了解作者常用印文和不同时期的用印习惯，比如齐白石早年用"齐璜"，中年后多用"白石"；二是印泥颜色，不同年代的印泥颜色有差异，老印泥沉稳有渗透感，新印泥鲜艳浮于表面，做旧的假印颜色不自然；三是钤印力度和清晰度，真印钤盖有轻重变化，边缘自然，假印往往过于均匀或模糊；四是印章风格与作者书画风格是否统一。需要注意的是，印章可以被翻刻仿制，所以印章只是参考之一，要结合笔墨综合判断。建议您拍几张印章高清图，我帮您分析一下。',
         '印章,鉴别,印泥,真伪', '字画印章鉴别方法与要点', 85
  UNION ALL SELECT 'art_calligraphy', '手里有幅字画想送去拍卖，有什么建议？',
         '您好，字画送拍是个不错的选择，但需要注意几个方面：一是选择拍卖行，知名大拍如嘉德、保利、匡时门槛较高但影响力大，适合名家精品；中小拍卖行门槛低但影响力有限，适合中档作品；二是了解送拍流程，一般需要先发送作品照片初审，通过后送实物鉴定，再签委托合同；三是关注费用，拍卖行会收取佣金（一般10%到15%）和图录费、保险费等，要了解清楚；四是合理估价，不要期望过高，参考同类拍品成交价定价；五是注意时间节点，春拍秋拍征集时间不同，提前联系。建议您先拍高清图发给拍卖行初审。您能告诉我作者和大致价值吗？',
         '拍卖,送拍,委托,估价', '字画送拍流程与注意事项', 87
  UNION ALL SELECT 'art_calligraphy', '字画可以砍价吗？怎么和卖家讨价还价？',
         '您好，闲鱼上买字画当然可以砍价，但要注意方式方法。砍价建议：一是先做功课，了解同类作品的市场行情，做到心中有数；二是找合理理由，比如品相瑕疵、无证书无著录、装裱老化需要重裱等，有理有据地谈价；三是出价不要过低，太低的出价会让卖家觉得没诚意直接拒绝，一般从七折左右开始谈；四是表达诚意，可以说明自己真心喜欢、爽快付款等，让卖家愿意让步；五是适可而止，如果价格已经在合理区间就不要死缠烂打。另外建议选择支持验货的卖家，收到后确认品相与描述一致再确认收货。您看中的是哪幅字画？我帮您分析下合理价位。',
         '砍价,讨价还价,购买技巧,议价', '字画砍价技巧与议价策略', 84
  UNION ALL SELECT 'art_calligraphy', '画家去世后作品会升值吗？什么时候买合适？',
         '您好，画家去世后作品确实有升值可能，但不是绝对的。去世后升值的原因主要是作品存量不再增加，供给固定而需求可能上升。但升值与否取决于几个因素：一是画家的艺术成就和市场地位，名家大师去世后大概率升值，普通画师则不一定；二是升值有时间滞后性，刚去世时可能被炒作一波，真正的价值发现需要时间沉淀；三是精品和代表作升值明显，应酬之作涨幅有限。建议如果是投资目的，关注年事已高且艺术成就突出的老画家精品，但首要还是自己喜欢。不建议纯粹为了"等去世"而收藏，这种心态不好。您有关注的具体画家吗？',
         '升值,去世,投资,市场', '画家去世对作品价值的影响分析', 86
  UNION ALL SELECT 'art_calligraphy', '字画揭裱有风险吗？什么情况需要揭裱？',
         '您好，字画揭裱确实有风险，需要谨慎决定。揭裱是指把画心从旧裱上揭下来重新装裱，风险在于：一是可能损伤画心，特别是老画纸绢脆弱，揭裱过程中可能造成破损；二是可能影响画面的墨色和颜色，揭裱用水和操作可能导致墨色晕染或褪色；三是如果裱画师技术不过关，后果不可逆。需要揭裱的情况：旧裱严重老化发脆无法保护画心；旧裱有霉变虫蛀危及画心；画心被劣质裱工损坏需要修复。不需要揭裱的情况：原裱完好或仅轻微老化；名家原装老裱有保留价值。建议找有经验的老师傅操作，先咨询评估再决定。您这幅字画是什么情况？',
         '揭裱,修复,装裱,风险', '字画揭裱的风险与适用场景', 82
  UNION ALL SELECT 'art_calligraphy', '字画配什么框好看？配框有什么讲究？',
         '您好，字画配框确实有讲究，配得好能提升整体观感和档次。配框建议：一是根据画心风格选框，传统国画配中式画框或实木原色框，现代水墨可配简约金属框；二是框的颜色要衬托画心，深色画心配浅色框提亮，浅色画心配深色框压重；三是框的宽窄要协调，大幅作品用宽框显大气，小幅作品用窄框显精致；四是卡纸选择，用卡纸留白能增加层次感和正式感，颜色以米白、浅灰为佳；五是玻璃选择，建议用防紫外线的博物馆玻璃或亚克力，保护画面且反光少。如果是珍贵作品建议不做永久性装框，方便取下检查和保存。您这幅画心是什么风格和尺寸？',
         '配框,装裱,展示,保养', '字画配框的讲究与建议', 80
  UNION ALL SELECT 'art_calligraphy', '水墨画和彩墨画有什么区别？哪种更值钱？',
         '您好，水墨画和彩墨画都是中国画的重要形式，区别主要在用色：水墨画纯用墨色作画，通过墨的浓淡干湿变化表现物象，讲究"墨分五色"；彩墨画在水墨基础上施以色彩，墨色与颜色结合，画面更丰富。哪种更值钱不能一概而论：从画家个人看，要看其擅长领域和代表作类型；从市场看，工笔重彩通常比纯水墨贵，因为工笔创作耗时更长、技术要求更高；但顶级名家的水墨精品价格同样很高。收藏建议以作品的艺术水准为主，不必纠结于水墨还是彩墨。您看中的是哪种类型的作品？',
         '水墨,彩墨,区别,价值', '水墨画与彩墨画的区别与价值比较', 78
  UNION ALL SELECT 'art_calligraphy', '买字画收到货怎么验货？要注意什么？',
         '您好，字画收到货后验货非常重要，建议您按以下步骤仔细检查：一是先对照商品描述核对作品信息，包括作者、尺寸、题材是否一致；二是检查整体品相，看是否有描述中未提及的破损、污渍、虫蛀、霉斑；三是检查装裱状况，裱工是否完好有无开胶脱裱；四是仔细看画面，有无修补痕迹、做旧痕迹；五是核对附件，如证书、著录等是否齐全；六是建议当面拆包全程录像，发现问题及时拍照留证。如果品相与描述严重不符或发现重大瑕疵，可以在闲鱼申请退款退货。验货确认无误后再确认收货。您收到货后有任何疑问都可以随时联系我。',
         '验货,签收,品相检查,维权', '字画收货验货流程与注意事项', 88
  UNION ALL SELECT 'art_calligraphy', '字画买回来不满意可以退货吗？退货规则是什么？',
         '您好，闲鱼上买字画的退货规则要看具体情况：一是如果卖家承诺了"七天无理由退货"，在商品未损坏的前提下可以申请退货；二是如果收到的作品与描述严重不符，比如作者不符、尺寸不对、品相问题未披露等，属于描述不符可以申请退款退货；三是如果只是个人审美不喜欢但作品本身没问题，且卖家未承诺无理由退货，则退货需要和卖家协商。建议购买前就和卖家确认好退货政策，保留聊天记录作为证据。收到货后先验货再确认收货，确认收货后发现问题处理难度会增大。您是已经买了遇到问题，还是在考虑买？',
         '退货,退款,维权,规则', '字画退货规则与维权指南', 85
  UNION ALL SELECT 'art_calligraphy', '书法的字看不懂，怎么判断写得好不好？',
         '您好，书法鉴赏确实需要一定积累，但也有一些基本的判断标准可以参考：一是看笔法，好的书法用笔有力有节奏，线条有粗细干湿变化，起笔收笔交代清楚，差的书法线条软弱或僵硬；二是看结体，好的书法每个字的结构匀称合理、疏密得当，有美感，差的书法结体松散或失衡；三是看章法，整幅作品的布局、字与字行与行之间的关系是否协调，有无气韵贯通；四是看格调，好的书法有书卷气和艺术感染力。建议多看名帖名碑培养感觉，可以从楷书入手比较好理解。您方便发给我看看是什么内容吗？我帮您解读一下。',
         '书法,鉴赏,笔法,结体', '书法鉴赏的基本判断标准', 83
  UNION ALL SELECT 'art_calligraphy', '字画邮寄怎么包装才安全？怕运输损坏。',
         '您好，字画邮寄的包装确实非常重要，运输损坏是字画交易中最常见的问题。包装建议：一是卷好画心后用干净的宣纸或棉纸包裹，防止画心直接接触包装材料；二是用硬纸筒作为外包装，纸筒两端用泡沫或纸团填充固定，防止画在筒内晃动；三是如果是装裱好的镜片或画框，要用泡沫板和硬纸板做夹板保护，四角加护角；四是在包裹上标注"易碎品""勿压""小心轻放"等提示；五是选择靠谱的快递公司，建议保价，贵重作品建议发顺丰特快或专递；六是提醒卖家打包时全程拍照录像，以备运输纠纷时取证。您是买家还是卖家？我给您更具体的建议。',
         '邮寄,包装,运输,安全', '字画邮寄包装的安全规范', 86
  UNION ALL SELECT 'art_calligraphy', '这幅画有签名但查不到这个画家，能买吗？',
         '您好，查不到画家信息的情况在字画交易中比较常见，不一定代表作品没有价值。可能有几种情况：一是画家是地方性或民间画家，知名度不高但画功不错；二是画家使用字号或别名，与身份证名不同查不到；三是名字有误或落款模糊导致搜索不到。建议您从作品本身的艺术水准来判断：如果画功扎实、画面美观、价格合理，作为家居装饰或个人喜好是可以入手的；但如果期望投资升值，查不到作者信息的作品风险较大，不建议高价购买。您可以多拍几张图，特别是落款和印章的高清图，我帮您看看能否辨识出更多信息。',
         '来源,查无此人,购买建议,风险', '查无画家信息的字画购买建议', 81
  UNION ALL SELECT 'art_calligraphy', '字画市场行情怎么样？现在买合适吗？',
         '您好，字画市场行情近年来有所分化，给您分析一下整体趋势：一是名家精品依然坚挺，齐白石、张大千、傅抱石等大师的代表作在拍卖市场屡创新高；二是中低端市场承压，普通画家作品和应酬之作价格回落，买家更理性；三是当代水墨板块关注度上升，年轻藏家入场带来新风向；四是线上交易成为趋势，闲鱼、微拍堂等平台降低了收藏门槛。现在是买方市场，对买家比较有利，议价空间大。建议关注自己喜欢且价格合理的作品，以收藏心态而非纯投资心态入手。您有感兴趣的方向或预算范围吗？我帮您推荐。',
         '行情,市场,购买时机,趋势', '字画市场行情与购买时机分析', 89
  UNION ALL SELECT 'art_calligraphy', '字画上的题跋是什么意思？有题跋更值钱吗？',
         '您好，题跋是字画上除作者本人以外的题字和跋语，通常写在画心的上方、两侧或裱边上。题跋一般分为几类：一是同时代人的题跋，记录作品创作背景或与作者的交往；二是后人收藏鉴赏的题跋，表达观感和评价；三是名家考证鉴定题跋，对作品真伪和价值做出判断。有题跋确实通常更值钱，原因：一是题跋者如果是名人，本身就增加了作品的文化价值；二是题跋提供了传承有序的证据链；三是题跋内容可能揭示作品的创作背景和历史价值。不过也要注意，题跋也有仿造的，需要鉴别。您这幅画上的题跋内容能拍给我看看吗？',
         '题跋,收藏价值,传承,鉴定', '字画题跋的意义与价值影响', 84
  UNION ALL SELECT 'art_calligraphy', '字画的著录是什么意思？有著录的作品更值钱吗？',
         '您好，著录是指字画被收录在权威出版物中的记录，比如拍卖图录、画册、展览图录、学术著作等。有著录的字画确实更值钱，原因：一是佐证真实性，被权威出版物收录过的作品可信度高，相当于有了专业背书；二是传承有序，著录提供了作品流传的历史记录，形成证据链；三是学术认可，被学术著作收录说明作品有艺术研究价值。著录的可信度分级：一是权威拍卖行图录（如嘉德、保利）最有说服力；二是正式出版的画册和学术著作；三是展览图录。购买有著录的字画时，建议核实著录的真实性，有些卖家会编造虚假著录。您可以查一下该著录书籍是否真实存在、是否收录了该作品。您看中的字画有著录吗？',
         '著录,收藏价值,传承,鉴定', '字画著录的意义与价值影响', 86
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;


-- ============================================================
-- 2. 邮票钱币 (art_stamp_coin) - 30条
-- ============================================================
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.58', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'art_stamp_coin' AS code, '老邮票怎么辨别真假？新手怎么看？' AS question,
         '您好，老邮票的鉴别是集邮的基本功，几个要点供参考：一看齿孔，真票齿孔大小均匀、孔缘光滑，假票齿孔常不规则或有毛刺；二看纸质，真票用专用邮票纸，有特定纹理和厚度，假票用普通纸张手感不同；三看印刷工艺，真票多为影写版或雕刻版，图文精细有凹凸感，假票多为胶印平面呆板；四看背胶，老票的背胶有时代特征，假票背胶不自然或重新刷胶；五看水印，部分老票有水印，透光可见。建议新手备一个放大镜和紫光灯，从低价票开始练眼力。您有具体的邮票想鉴定吗？发图给我看看。' AS answer,
         '真假辨别,邮票,齿孔,印刷' AS tags, '老邮票真伪鉴别要点' AS source_summary, 90 AS score
  UNION ALL SELECT 'art_stamp_coin', '邮票品相怎么分级？什么样的品相才值钱？',
         '您好，邮票品相对价格影响非常大，品相分级主要看几个方面：一是新票看背胶，全品原胶（未贴未洗）最贵，二胶（重新刷胶）次之，无胶再次之；二是看齿孔是否完整，有无缺齿短齿；三是看票面是否洁净，有无污渍折痕黄斑；四是看颜色是否鲜艳，有无褪色；五是看是否端正，有无倾斜。全品相的老票价格可能是中品的两到三倍。购买时建议要求卖家拍高清图，特别是背胶和齿孔部位。如果投资收藏建议只买全品，如果把玩欣赏中品也可以但价格要相应低。您手上的邮票是什么品相？',
         '品相,背胶,齿孔,分级', '邮票品相分级标准与价值关系', 88
  UNION ALL SELECT 'art_stamp_coin', '庚申年猴票现在值多少钱？怎么知道是真的？',
         '您好，1980年庚申年猴票是新中国邮票的"邮王"，目前全品相的市场价在万元到几万元不等，具体看品相和版式。猴票的鉴别要点：一看版别，真票是影雕套印，雕刻版线条有凹凸手感，假票多为胶印无凹凸感；二看猴毛，真票猴身上的毛发根根分明有雕刻版的锐利感，假票毛发模糊；三看红色背景，真票红色鲜艳沉稳，假票红色偏暗或偏橙；四看背胶，真票是原生胶有特定光泽；五看齿孔，真票齿孔为11度半，规整光滑。建议高价邮票一定要当面交易或找权威评级机构鉴定。您有猴票要出手还是想买？',
         '猴票,真假辨别,市场价,鉴定', '庚申猴票价值与真伪鉴别', 93
  UNION ALL SELECT 'art_stamp_coin', '银元的包浆怎么看真假？老包浆和做旧的怎么区分？',
         '您好，银元包浆是鉴定银元真假的重要依据，老包浆和做旧包浆的区别：老包浆是银元在自然环境中长期氧化形成的，色泽温润有层次感，不同部位因接触环境不同包浆颜色有自然过渡，常见有浅金、彩虹、黑灰、蓝紫等色泽，且包浆入骨有附着感。做旧包浆是用化学药剂或人工方法加速氧化形成的，常见问题：一是颜色单一不自然，没有层次变化；二是包浆浮于表面，用酒精棉签擦拭会掉色；三是包浆分布不均匀，刻意做作；四是气味异常，化学做旧可能有药水味。建议多看真品包浆培养感觉，上手摸的质感很重要。您发张图我帮您看看。',
         '包浆,银元,做旧,真假辨别', '银元包浆真伪鉴别方法', 89
  UNION ALL SELECT 'art_stamp_coin', '袁大头怎么鉴定真假？新手怎么快速判断？',
         '您好，袁大头的鉴定有几个快速判断方法：一看压力，真币压力足图文深峻清晰，假币压力不足图文发软模糊；二听声音，真银元吹气后放在嘴边轻吹有清脆悠长的"嗡嗡"共鸣声，假币声音发闷或尖利；三掂重量，真币标准重量约26.8克，假币常偏轻或偏重；四看齿边，真币齿边均匀细密有力度，假币齿边粗糙不规整；五看包浆，真币包浆自然温润，假币包浆做作或无包浆；六看材质，真币含银量约89%，色泽柔和有银白色光泽。新手建议先从重量和声音入手快速筛选，再结合图文细节判断。最好备个电子秤。您手上的袁大头方便称一下重量吗？',
         '袁大头,银元,鉴定,真假辨别', '袁大头银元快速鉴定方法', 91
  UNION ALL SELECT 'art_stamp_coin', '邮票的背胶怎么看？原胶和二胶怎么区分？',
         '您好，邮票背胶的鉴别对老邮票价值影响很大，原胶和二胶的区别：原胶是邮票出厂时机器刷的胶，特点是胶面均匀平整有光泽，胶纹方向一致，且有年代感（老胶会泛黄）；二胶是后期重新刷的胶，常见问题：一是胶面不均匀，有刷痕或胶疙瘩；二是胶纹方向与原胶不一致或杂乱；三是胶面过于白净新鲜，与票面年代不符；四是齿孔处有胶水渗出痕迹；五是紫外灯下二胶会有异常荧光反应。鉴别技巧可以用紫光灯辅助，原胶和二胶在紫外灯下荧光不同。原胶全品的老票比二胶贵30%到50%以上。您方便拍张背面高清图吗？',
         '背胶,原胶,二胶,邮票', '邮票原胶与二胶的鉴别方法', 87
  UNION ALL SELECT 'art_stamp_coin', '钱币评级封装是什么意思？评级币值得买吗？',
         '您好，钱币评级封装是由专业评级机构对钱币进行鉴定、评分并用密封盒封装的服务。国际知名评级机构有PCGS、NGC等，国内有公博、中乾等。评级的好处：一是权威鉴定保真，评级机构把关真伪；二是品相标准化，评分（如MS63、AU58等）客观反映品相；三是密封保护，封装后隔绝空气防止氧化；四是流通性好，评级币市场认可度高更容易出手。评级币值不值得买要看情况：如果是高价币或名贵品种，评级封装值得，增加流动性和公信力；如果是低价普通币，评级费不划算。建议买评级币认准正规机构和正确标签。您想了解哪家评级机构？',
         '评级,封装,PCGS,NGC', '钱币评级封装的意义与选择', 88
  UNION ALL SELECT 'art_stamp_coin', '纪念币有升值空间吗？哪种值得收藏？',
         '您好，纪念币的升值空间因品种而异，不是所有纪念币都能升值。升值潜力较大的几个方向：一是早期纪念币，如建国35周年、西藏自治区成立20周年等老币，发行量少存世量低；二是贵金属纪念币，金银币本身有贵金属价值托底，且发行量少；三是热门题材币，如生肖币、熊猫币等有持续关注度；四是评级高分币，MS69以上的高分币溢价明显。不建议收藏的：发行量巨大的普通纪念币（如近年部分流通纪念币），升值空间有限。收藏建议以系列收藏为主，保持品相完好，保留原包装和证书。您有看中的具体品种吗？',
         '纪念币,升值,收藏,投资', '纪念币升值空间与收藏方向', 86
  UNION ALL SELECT 'art_stamp_coin', '邮票水印怎么看？哪些邮票有水印？',
         '您好，邮票水印是防伪和鉴定的重要特征，部分国家发行的邮票纸中有水印。看水印的方法：将邮票背朝上放在深色桌面上，用强光从正面照射，或用水印盘（黑色小盘加水）观察。中国邮票中带水印的主要有：清代的蟠龙票有太极图水印；民国部分邮票有篆字水印；新中国早期部分邮票有五角星水印等。水印的形状、排列方式是鉴定邮票真伪和版式的重要依据，不同版式的同一图案邮票可能水印不同，价值差异很大。建议购买高价水印票时一定要验证水印，最好有水印盘或请专业人士协助。您手上的邮票是什么时期的？',
         '水印,邮票,防伪,鉴定', '邮票水印识别方法与意义', 84
  UNION ALL SELECT 'art_stamp_coin', '古钱币的锈色怎么看？老锈和假锈怎么区分？',
         '您好，古钱币的锈色是鉴定真假的重要依据。老锈（自然锈）的特点：一是层次丰富，锈色从浅到深有自然过渡，常见有绿锈、蓝锈、红锈、黑锈等；二是锈入骨，锈与钱体结合紧密，用刀刮感觉坚硬牢固；三是分布自然，不同部位因接触环境不同锈色有差异。假锈（人工做锈）的特点：一是颜色单一刺眼，没有层次变化；二是锈浮于表面，用针挑容易脱落；三是分布均匀做作，不自然；四是有化学药水气味。常见做锈方法有酸蚀法、胶水粘锈等。建议多上手真品培养对老锈的感觉，新手最好从评级币或有信誉的商家处购买。您发张图我帮您看看锈色。',
         '古钱币,锈色,老锈,假锈', '古钱币锈色真伪鉴别要点', 87
  UNION ALL SELECT 'art_stamp_coin', '邮票齿孔怎么辨伪？齿孔度数是什么意思？',
         '您好，邮票齿孔是鉴别邮票真伪和版式的重要特征。齿孔度数是指每20毫米长度内的齿孔数量，比如P11表示每20毫米有11个齿孔。不同时期不同版式的邮票齿孔度数可能不同，是区分版别的重要依据。辨伪要点：一看齿孔是否规整，真票齿孔圆形光滑大小一致，假票齿孔常不规则；二看齿孔度数是否与该版式吻合，不吻合则可能是假票或错版；三看齿孔位置是否居中，真票齿孔与票面图案有固定位置关系。测量齿孔度数需要专门的齿孔度尺（量齿尺）。建议购买高价邮票时核实齿孔度数，新手可以备一把量齿尺。您有需要测量的邮票吗？',
         '齿孔,度数,辨伪,邮票', '邮票齿孔度数与辨伪方法', 83
  UNION ALL SELECT 'art_stamp_coin', '银元的标准重量是多少？重量不对就是假的吗？',
         '您好，银元的标准重量因品种而异，以最常见的袁大头为例，标准重量约26.8克（含银89%），允许有0.1到0.2克的正常磨损误差。常见银元重量参考：袁大头约26.8克，孙小头约26.8克，船洋约26.8克，龙洋约26.8到27克。重量不对确实是判断真假的重要参考：偏轻可能是假币或磨损严重的真币，偏重可能是铁芯镀银等假币。但重量对不一定真，因为现代假币也能做到标准重量。所以重量是必要条件但非充分条件，要结合压力、图文、包浆、声音等综合判断。建议备一个0.01克精度的电子秤。您手上的银元多重？',
         '银元,重量,标准,鉴定', '银元标准重量与鉴定参考', 85
  UNION ALL SELECT 'art_stamp_coin', '评级币和裸币价格差多少？买哪个划算？',
         '您好，评级币和裸币的价格差异取决于多个因素：一是品种，高价币的评级溢价大，低价币的评级溢价小甚至不划算；二是评分，高分币（MS65以上）溢价明显，低分币溢价小；三是机构，PCGS和NGC的评级币溢价高于国内机构。一般同品种同品相的评级币比裸币贵20%到50%，高分币可能贵一倍以上。买哪个划算：如果是高价币或名贵品种，建议买评级币，保真且流动性好；如果是低价币或自己把玩欣赏，裸币更划算，但要有鉴别能力。新手建议从评级币入门，减少买到假币的风险。您是收藏还是投资？我帮您参考。',
         '评级币,裸币,差价,购买建议', '评级币与裸币的价格差异分析', 86
  UNION ALL SELECT 'art_stamp_coin', '邮票怎么保存？怕潮怕光吗？',
         '您好，邮票保存非常重要，保存不当会严重影响品相和价值。保存要点：一是防潮，邮票最怕潮湿，南方梅雨天要特别注意，建议用干燥剂放在存放处，相对湿度控制在50%到55%；二是避光，紫外线会使邮票褪色变色，避免阳光直射，最好用黑色护邮袋或护邮册存放；三是防霉防虫，存放处可放防霉防虫剂但不要直接接触邮票；四是使用专用工具，用护邮袋、护邮条、定位册等专业用品，不要用普通胶水或透明胶带粘贴；五是取放时用邮钳，避免手汗污染票面；六是避免温差骤变，防止票面产生凝结水。建议定期检查品相。您是南方还是北方的？',
         '保存,防潮,避光,维护', '邮票保存的防潮防光要点', 88
  UNION ALL SELECT 'art_stamp_coin', '第三套人民币现在值多少钱？哪张最值钱？',
         '您好，第三套人民币（1962年始发）是目前收藏市场关注度较高的版别，整体套币全品相市场价在数万元到十几万元不等，具体看每张的版式和品相。最值钱的是"背绿水印壹角"，目前全品相单张市场价在数万元，是第三套的"币王"；其次是"枣红一角"和"背绿无水印一角"，价值也在数千到上万元。其他面值中，贰角"武汉长江大桥"和贰元"车工"也有较高收藏价值。影响价格的因素：版式（如水印有无）、品相、冠号（如补号更贵）、连号或整刀更贵。建议收藏时重点关注品相和版式，保留原始状态不要清洗。您有具体哪张想了解？',
         '第三套人民币,市场价,背绿一角,车工', '第三套人民币价值与版别分析', 90
  UNION ALL SELECT 'art_stamp_coin', '银元含银量怎么检测？不上手能判断吗？',
         '您好，银元含银量的检测方法有几种：一是专业检测，X射线荧光光谱仪（XRF）可以无损检测含银量，但设备昂贵一般藏友不具备；二是比重法，通过测量银元的重量和体积计算密度，真银元密度约10.3，但操作复杂误差大；三是听声音，真银元轻吹有清脆悠长的共鸣声，假币声音发闷，这是最实用的方法；四是看色泽，真银色泽柔和有温润感，假银偏亮或偏暗。不上手仅凭照片很难判断含银量，建议购买时要求当面交易或选择支持退换的卖家。新手建议从评级币入手，评级机构已验证含银量。您方便去当面交易吗？',
         '银元,含银量,检测,鉴定', '银元含银量检测方法对比', 84
  UNION ALL SELECT 'art_stamp_coin', '信销票有收藏价值吗？值得收集吗？',
         '您好，信销票（已使用盖销的邮票）当然有收藏价值，是集邮的重要门类。信销票的价值取决于几个因素：一是稀缺性，早期信销票存世量少，有些比新票还稀少；二是邮戳信息，有特殊邮戳（如纪念邮戳、地名戳、干支戳等）的信销票更珍贵；三是品相，票面完整邮戳清晰为佳；四是实寄封价值，邮票连信封一起保存的实寄封比单独的信销票更有价值，能反映邮政历史。建议新手从收集信销票入门，成本低且有趣味性，通过研究邮戳可以学习很多邮政历史知识。如果您有实寄封建议保留原样不要剪票。您有具体的信销票想了解吗？',
         '信销票,邮戳,实寄封,收藏价值', '信销票的收藏价值与门类', 82
  UNION ALL SELECT 'art_stamp_coin', '钱币的原光怎么看？有原光的贵多少？',
         '您好，钱币的原光是指钱币出厂时币面因压制形成的金属光泽，是品相鉴定的重要指标。原光的特点：光泽自然柔和，从不同角度观察有转动效果（俗称"转光"），分布与压制纹路一致。原光的保存难度很大，流通使用或不当清洁都会破坏原光。有原光的钱币比无原光的贵很多，尤其是评级中"原光强"（如Mint State高分）的银元比普通流通币贵数倍甚至数十倍。需要注意的是，有些币商用化学方法做"假原光"，光泽刺眼不自然。建议多看真品原光培养感觉。您手上的钱币有光泽吗？发张图我帮您看看。',
         '原光,钱币,品相,光泽', '钱币原光的鉴别与价值影响', 85
  UNION ALL SELECT 'art_stamp_coin', '错版邮票值钱吗？怎么判断是错版？',
         '您好，错版邮票因为印刷错误或设计失误，存世量少，往往价值很高。著名的错版票如"全国山河一片红"因地图绘制错误被紧急回收，目前全品相市场价在数十万到上百万元。判断错版邮票要注意：一是区分"错版"和"变体"，错版是设计或制版错误（如倒印、漏色、错字等），变体是印刷过程中的偶然变异（如漏盖、折白、漏齿等）；二是要看错版是否被官方回收，被回收的错版票存世量少价值高；三是注意仿造的假错版，用化学方法做出来的"漏色"等不是真错版。建议高价错版票一定要通过权威渠道购买并鉴定。您有具体的错版票吗？',
         '错版,邮票,变体,收藏价值', '错版邮票的价值判断与鉴别', 88
  UNION ALL SELECT 'art_stamp_coin', '古钱币版别怎么看？同一品种版别不同价格差多少？',
         '您好，古钱币的版别研究是古钱收藏的核心乐趣，同一品种不同版别价格可能相差数十倍甚至上百倍。版别的区分主要看：一是文字特征，如字体大小、笔画粗细、书写风格等微细差异；二是穿口形制，如方穿圆穿、广穿狭穿等；三是外廓内廓特征，如阔缘狭缘、有无内廓等；四是材质重量，如大样小样、厚薄差异；五是铸地铸期，不同钱监不同时期的铸币有差异。比如北宋钱币版别多达数千种，稀少版别价值远超普通版。建议入门某朝代钱币时先买一本版别谱，对照学习。新手不要急于买高价版别币，先从普通版练眼力。您对哪个朝代钱币感兴趣？',
         '古钱币,版别,区分,价值', '古钱币版别研究入门指南', 86
  UNION ALL SELECT 'art_stamp_coin', '邮票册怎么收藏？买年册好还是散票好？',
         '您好，邮票册收藏有几种方式，各有优缺点：一是年册，每年发行的邮票汇编成册，优点是系统完整省心，适合新手入门；缺点是年册含部分低值票，整体性价比一般。二是专题册，按主题（如生肖、花卉、名画等）收集，趣味性强有个人特色。三是散票收集，自由度高可聚焦高值票和稀有票，性价比最好但需要较多专业知识。建议根据收藏目的选择：如果以欣赏和系统收藏为主，年册和专题册适合；如果以投资增值为主，散票收集高价值票更划算。购买年册注意品相和完整性，缺票的年册价值大打折扣。您是新手入门还是老手补充？',
         '邮票册,年册,散票,收藏方式', '邮票册收藏方式对比与建议', 81
  UNION ALL SELECT 'art_stamp_coin', '钱币上有磕碰影响价值吗？品相瑕疵怎么算？',
         '您好，钱币上的磕碰确实影响价值，影响程度取决于几个因素：一是磕碰的位置，正面比背面影响大，图文关键部位比边缘影响大；二是磕碰的程度，轻微划痕影响小，明显的磕碰坑或变形影响大；三是钱币本身的价值，高价币的瑕疵影响更大，因为高价币买家对品相要求高；四是评分影响，评级币的磕碰会直接拉低评分。一般有磕碰的钱币比全品便宜20%到40%，具体看严重程度。建议购买时要求卖家拍清磕碰部位的高清图，评估是否可接受。如果只是把玩欣赏，有轻微瑕疵但价格合适也可以入手。您手上的钱币磕碰严重吗？',
         '品相,磕碰,瑕疵,价值评估', '钱币磕碰对价值的影响评估', 80
  UNION ALL SELECT 'art_stamp_coin', '纪念钞冠号怎么看？哪些冠号值钱？',
         '您好，纪念钞冠号是影响价值的重要因素。冠号是钞票编号前面的字母或汉字组合。值钱的冠号类型：一是补号，用于替换印刷废品的补充冠号，发行量少因此更值钱；二是开门号和关门号，如00000001开头或最大编号；三是特殊号码，如豹子号（同号）、顺子号、生日号等有收藏趣味性；四是首发冠号，某版别的第一个冠号有纪念意义。纪念钞的冠号收藏建议：全品相是前提，冠号特殊是加分项，但不要为特殊冠号付过高溢价。注意号码收藏是个人偏好，市场认可度因品种而异。您手上的纪念钞是什么冠号？',
         '纪念钞,冠号,补号,特殊号码', '纪念钞冠号收藏与价值分析', 83
  UNION ALL SELECT 'art_stamp_coin', '现在邮票市场行情怎么样？还有收藏价值吗？',
         '您好，邮票市场近年确实比较低迷，给您客观分析：一是老纪特和文革票等经典老票依然坚挺，存世量少有固定藏家群体；二是编年票（1992年后）发行量大，市场价多在面值附近甚至打折，升值空间有限；三是小型张和小版张等热门品种波动较大，受市场情绪影响明显；四是评级邮票开始流行，高分评级票有溢价。邮票收藏的价值不仅在投资升值，更在于文化学习和乐趣。建议以收藏心态入手，不要期望短期暴富。如果投资建议聚焦经典老票和评级高分票。您有感兴趣的具体方向吗？',
         '行情,邮票市场,收藏价值,投资', '邮票市场行情与收藏价值分析', 87
  UNION ALL SELECT 'art_stamp_coin', '钱币被洗过影响价值吗？洗币好不好？',
         '您好，钱币清洗对价值的影响非常大，一般建议不要清洗。清洗的问题：一是破坏原光，原光是钱币出厂的金属光泽，一旦清洗基本无法恢复；二是破坏包浆，老包浆是岁月痕迹也是鉴定依据，清洗后包浆消失；三是损伤币面，化学清洗剂可能腐蚀币面，物理清洗会产生划痕；四是降低评级分，评级机构对清洗过的钱币会降分或标注"清洗"。唯一可以考虑清洗的情况：钱币表面有影响保存的污垢或有害锈，且由专业人士操作。市场上清洗过的钱币比原生态的便宜30%到50%以上。建议保持原样，不要自行清洗。您的钱币是什么情况？',
         '洗币,清洗,品相,原光', '钱币清洗对价值的影响分析', 86
  UNION ALL SELECT 'art_stamp_coin', '邮票连票和方连值钱吗？比单票贵多少？',
         '您好，邮票的连票和方连确实比单票更值钱，但贵多少要看品种和连票形式。连票形式：一是方连，四枚邮票连在一起成方形，保留了完整的齿孔间距信息，品相好的方连比单票贵30%到100%；二是直连，两枚或多枚横向连在一起；三是带边纸的连票，边纸上有版铭等信息，更有收藏和研究价值；四是整版票，完整的全版邮票，价值最高。连票的溢价逻辑：连票能反映邮票的齿孔、版式等原始信息，且存世量比单票少。建议收藏时优先选择方连或带边纸连票，增值空间更大。您手上的邮票是连票还是单票？',
         '连票,方连,整版,收藏价值', '邮票连票方连的价值分析', 82
  UNION ALL SELECT 'art_stamp_coin', '怎么判断钱币包浆是做旧的？化学做旧有什么特征？',
         '您好，钱币做旧包浆的鉴别是收藏的重要技能。化学做旧的常见特征：一是颜色不自然，做旧包浆颜色单一刺眼，缺乏自然包浆的层次感和温润感；二是分布不匀，自然包浆因接触环境不同有自然过渡，做旧包浆分布刻意均匀或不自然；三是附着不牢，用酒精或丙酮棉签轻擦，做旧包浆会掉色，自然包浆不会；四是气味异常，化学做旧可能残留药水气味；五是微观特征，放大镜下做旧包浆有化学腐蚀痕迹，自然包浆是均匀氧化层。常见做旧方法有硫化、硝酸、烟熏等。建议多上手真品包浆培养感觉，新手从评级币入门。您发张图我帮您看看。',
         '包浆,做旧,化学,鉴别', '钱币做旧包浆的鉴别特征', 85
  UNION ALL SELECT 'art_stamp_coin', '钱币评级选哪家机构好？PCGS和NGC怎么选？',
         '您好，钱币评级机构的选择确实重要，主流机构对比：PCGS是美国老牌评级机构，全球认可度最高，评级严格标准统一，评级币流动性最好但评级费较贵；NGC也是美国知名机构，认可度与PCGS接近，评分相对略宽松，适合银元和中国机制币；国内机构如公博（GBCA）、中乾等，评级费便宜，但国际认可度不及PCGS和NGC。选择建议：如果是高价币或打算未来出手，建议选PCGS或NGC，国际流通性好；如果是中低价币自藏，国内机构性价比高。注意不同机构评分标准有差异，不要简单跨机构比分数。您的钱币大概价值多少？我帮您参考。',
         '评级,PCGS,NGC,机构选择', '钱币评级机构对比与选择建议', 88
  UNION ALL SELECT 'art_stamp_coin', '邮票实寄封怎么保存？为什么实寄封比剪票值钱？',
         '您好，实寄封（邮票连信封一起保存的实寄邮件）的保存和收藏都很有讲究。实寄封比剪票值钱的原因：一是邮政历史价值，实寄封完整保留了邮戳、邮路、邮资等邮政信息，是邮政史研究的重要实物；二是稀缺性，实寄封的存世量远少于单枚邮票；三是品相完整性，邮票在信封上保存的环境比单独存放更稳定。保存要点：一是用专用护封袋或护封册存放，避免折压和潮湿；二是保持原样不要清洗或处理邮戳；三是避免阳光直射防止褪色；四是记录封上的邮政信息便于研究。建议收到实寄封时不要剪票，保留完整封。您有实寄封想了解吗？',
         '实寄封,邮戳,保存,收藏价值', '实寄封的保存方法与价值分析', 84
  UNION ALL SELECT 'art_stamp_coin', '手里的钱币想出手，去哪里卖比较好？',
         '您好，钱币出手的渠道有几个选择，各有优缺点：一是闲鱼等二手平台，优点是门槛低自己定价，缺点是需要自己拍照描述，遇到砍价和纠纷；二是钱币论坛或微信群，优点是藏家聚集成交快，缺点是需要信誉积累；三是送拍拍卖行，优点是高价币可能拍出好价，缺点是周期长有佣金；四是钱币市场门店，优点是当面交易快速变现，缺点是商家压价利润空间小；五是评级后出售，评级币更容易卖且价格更好。建议根据钱币价值和自身情况选择：低价币走闲鱼或论坛，高价币建议评级后送拍。您手里的钱币大概值多少？',
         '出手,渠道,回购,销售', '钱币出手渠道对比与建议', 86
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;


-- ============================================================
-- 3. 古董收藏 (art_antique) - 30条
-- ============================================================
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.58', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'art_antique' AS code, '这个瓷器怎么辨别真假？老瓷器怎么看年代？' AS question,
         '您好，瓷器辨伪和断代是古董收藏的基本功，给您介绍几个要点：一看釉面，老瓷器釉面温润有自然老化痕迹（称为"包浆"），新瓷器釉面火光刺眼；二看胎质，不同年代窑口的胎质有区别，老胎致密有自然老化，新胎粗糙或过于规整；三看器型，每个时代的器型有时代特征，比例和线条有讲究；四看纹饰，绘画风格、纹样题材有时代特征；五看底足，老瓷器底足有自然磨损和使用痕迹，修胎方式有时代差异；六看气泡，用放大镜看釉下气泡，老瓷器气泡有自然老化死亡现象。建议多去博物馆看真品培养眼力。您有具体什么瓷器？发图我帮您看看。' AS answer,
         '真假辨别,瓷器,断代,包浆' AS tags, '瓷器辨伪断代要点' AS source_summary, 91 AS score
  UNION ALL SELECT 'art_antique', '古董的包浆怎么看？老包浆和做旧包浆怎么区分？',
         '您好，古董包浆是岁月在器物表面形成的自然氧化层，是鉴定老货的重要依据。老包浆的特点：一是色泽温润，有自然的光泽和质感，不刺眼不油腻；二是分布自然，不同部位因接触和磨损程度不同包浆有深浅变化；三是层次丰富，包浆不是一层均匀的膜，而是有层次感的；四是手感舒适，盘玩过的老包浆手感滑润。做旧包浆的问题：一是色泽不自然，过于均匀或过于暗沉；二是分布做作，刻意做出来的缺乏自然变化；三是手感发涩或发腻，没有老包浆的温润感；四是化学做旧可能有药水残留气味。建议多上手真品培养手感。您发张图我帮您看看包浆。',
         '包浆,做旧,真假辨别,手感', '古董包浆真伪鉴别方法', 88
  UNION ALL SELECT 'art_antique', '这个老物件是什么年代的？怎么看古董的年代？',
         '您好，古董断代需要综合多个方面判断：一是器型风格，每个时代的器物造型有时代特征，比如唐代丰满大气、宋代清雅修长、明清繁复精致；二是材质工艺，不同时期使用的材料和制作工艺有差异；三是纹饰题材，纹样风格和题材有时代流行趋势；四是款识铭文，有纪年款的直接断代，无款的要靠风格类比；五是包浆和老化程度，自然老化的痕迹与年代大致对应；六是科学检测，碳14、热释光等检测方法可辅助断代。断代需要丰富的实物经验和文献知识，新手建议多看博物馆真品，从有款的标本入手学习。您这件是什么材质的器物？',
         '年代,断代,器型,纹饰', '古董断代的多维度方法', 87
  UNION ALL SELECT 'art_antique', '瓷器开片是怎么回事？有开片的就是老的吗？',
         '您好，瓷器开片是指釉面出现的裂纹，分两种：一是自然开片，是瓷器在长期使用和保存中因釉面和胎体膨胀系数不同，经历温度变化自然形成的裂纹，裂纹自然不规则，有岁月感；二是人为开片，是工匠在烧制时通过控制釉料配方和烧制温度有意形成的装饰效果（如哥窑的金丝铁线）。有开片不一定就是老瓷器，因为：一是现代仿品也能做出开片效果；二是新瓷器时间长了也可能开片。判断开片是否自然要看：裂纹的形态是否自然（老开片有深浅变化和沁色），开片与器物整体老化是否协调。您发张开片细节图我帮您看看。',
         '开片,瓷器,哥窑,老化', '瓷器开片的成因与鉴别', 84
  UNION ALL SELECT 'art_antique', '古董的来源重要吗？没有发票证书能买吗？',
         '您好，古董的来源（传承有序）非常重要，但也不绝对。来源清晰的好处：一是降低真伪风险，有明确传承的古董可信度高；二是提升市场价值，传承有序的古董在拍卖市场溢价明显；三是方便出手，有来源记录的古董买家更放心。没有发票证书的古董能不能买要看情况：地摊和旧货市场的古董大多没有来源记录，价格低但风险大；闲鱼上的古董来源不一，要仔细甄别。建议新手从有信誉的商家或有传承记录的古董入手，虽然价格贵一些但风险低。高价古董一定要追溯来源，不要来历不明的。您看中的是什么器物？',
         '来源,传承,证书,购买建议', '古董来源的重要性与购买建议', 85
  UNION ALL SELECT 'art_antique', '古董有鉴定证书就一定是真的吗？证书怎么看？',
         '您好，古董鉴定证书的含金量要分别看待，有证书不等于一定是真品。证书的可靠性看几个方面：一是鉴定机构，国家文物部门、省级博物馆、知名拍卖行的鉴定比较有公信力，一些商业鉴定机构的证书可信度存疑；二是鉴定方法，科学检测（如热释光、碳14）比眼学鉴定更客观；三是鉴定人资质，有文博专业职称的鉴定师比"自学成才"的可靠。需要注意的是，古董鉴定没有百分百准确，即使是权威机构也有走眼的时候。建议证书作为参考，自己也要学习鉴别知识，高价古董最好多家鉴定交叉验证。您有具体的证书想了解吗？',
         '证书,鉴定,机构,可信度', '古董鉴定证书的可靠性分析', 83
  UNION ALL SELECT 'art_antique', '古董有破损还值钱吗？修复过的古董影响价值吗？',
         '您好，古董有破损对价值确实有影响，但影响程度取决于多个因素：一是器物的稀缺性，稀缺品种即使有残依然有价值，甚至残器也是藏家争抢的对象（如宋代五大名窑残件）；二是破损程度和位置，小冲线（细裂纹）比大缺口影响小，底部比腹部影响小；三是修复质量，专业"金缮"或"锔瓷"修复不仅不贬值还可能增加艺术价值，劣质胶水修复则影响品相。修复过的古董比完整器便宜很多，是新手入门的好选择，可以用较低价格接触到真品。建议购买时如实了解修复情况，不要被掩盖修复的器物误导。您看中的器物破损严重吗？',
         '破损,修复,金缮,价值评估', '古董破损修复对价值的影响', 84
  UNION ALL SELECT 'art_antique', '古董的市场价怎么定？怎么知道卖家报价合不合理？',
         '您好，古董定价是收藏中最难的问题之一，没有标准价，只有市场价。估价参考几个渠道：一是拍卖记录，查阅雅昌、嘉德、保利等拍卖行的同类器物成交价，注意区分品相和尺寸差异；二是古玩市场行情，去实体古玩城了解同类器物的标价和成交价；三是专业估价平台，有些平台提供付费估价服务；四是请教行家，多向有经验的藏友或商家请教。判断卖家报价是否合理：对比同类器物的市场成交价，考虑品相、尺寸、稀缺性差异。建议新手多看少买，先积累行情认知再出手。您看中的是什么器物？大概什么价位？',
         '市场价,定价,估价,行情', '古董估价方法与行情参考', 86
  UNION ALL SELECT 'art_antique', '新手想收藏古董，有什么入门建议？',
         '您好，古董收藏水深，新手入门给几点建议：一是先学后买，多看博物馆、多读专业书籍、多看拍卖预展，培养鉴赏能力，不要急着出手；二是聚焦一个门类，不要什么都碰，选择自己感兴趣且有条件深入的方向，如瓷片、铜镜、文房等；三是从标本和残件入手，价格低且能学到真品特征，是练眼力的好教材；四是不贪便宜，天上不会掉馅饼，远低于市场价的"宝贝"基本是赝品；五是多交藏友，加入收藏圈交流学习，少走弯路；六是量力而行，用闲钱收藏不要影响生活。最重要的是保持学习心态，收藏是一辈子的修行。您对哪个门类感兴趣？',
         '入门,新手,收藏建议,学习', '古董收藏新手入门指南', 91
  UNION ALL SELECT 'art_antique', '古董怎么保养？老物件保养有什么讲究？',
         '您好，古董保养非常重要，保养不当会造成不可逆的损伤。不同材质保养要点：瓷器要防磕碰，用软布包裹存放，清洗用温水不用化学剂，手拿时托底不要抓把手；铜器要防潮防锈，保持干燥，有有害锈要及时处理；木器要防干裂防虫蛀，保持适宜湿度（50%到60%），定期打蜡保养，放防虫剂；玉器要防磕碰防高温，定期用清水清洗，避免接触化学物品；书画要防潮防虫防光（详见字画保养）。通用原则：轻拿轻放，避免温湿度剧烈变化，定期检查，不要自行修复。建议每件古董都了解其材质特性，对症保养。您收藏的是什么材质？',
         '保养,维护,存放,材质', '古董保养的材质分类指南', 88
  UNION ALL SELECT 'art_antique', '玉器怎么辨别真假？和田玉和翡翠怎么鉴别？',
         '您好，玉器鉴别是古董收藏中的热门话题。和田玉鉴别：一看质地，真和田玉温润细腻有油性光泽，假料干涩或过于透亮；二看结构，和田玉有纤维交织结构，透光可见云絮状纹理；三看密度，和田玉密度约2.95，手感沉甸；四看硬度，和田玉摩氏硬度6到6.5，能划动玻璃。翡翠鉴别：一看翠性，真翡翠有"苍蝇翅"反光；二看颜色，天然翡翠颜色有根有层次，染色翡翠颜色浮于表面；三看结构，翡翠有纤维交织到粒状结构；四听声音，A货翡翠敲击声清脆。建议购买玉器一定要看鉴定证书，最好去权威机构复检。您有具体的玉器想鉴定吗？',
         '玉器,和田玉,翡翠,真假辨别', '玉器鉴别方法与要点', 89
  UNION ALL SELECT 'art_antique', '老木器的包浆怎么看？怎么判断是老红木还是新料？',
         '您好，老木器的鉴别主要从几个方面入手：一看包浆，老木器表面有自然形成的包浆，温润有光泽，使用频繁的部位包浆深，少碰触的部位包浆浅，过渡自然；新料做旧包浆不自然，颜色过于均匀或有化学处理痕迹。二看纹理，老红木纹理自然流畅，有岁月沉淀的深沉色泽；新料纹理生硬颜色偏浅。三看工艺，老家具榫卯结构精巧，手工痕迹明显；新仿多用机器加工或胶水粘合。四看磨损，老家具自然磨损在使用部位，边缘圆润；做旧磨损刻意不自然。五看材质，不同年代流行不同木材，如明清多用黄花梨紫檀，民国多用红酸枝。您发张图我帮您看看。',
         '木器,包浆,红木,新老鉴别', '老木器包浆与材质鉴别', 86
  UNION ALL SELECT 'art_antique', '铜器的锈色怎么看？老铜器的锈和假锈怎么区分？',
         '您好，铜器锈色是鉴定老铜器的重要依据。老铜锈（自然锈）的特点：一是层次丰富，锈色有绿锈、蓝锈、红锈、黑锈等多种，且从表层到深层有自然过渡；二是锈入骨，锈与铜体结合紧密，用刀刮感觉坚硬难除；三是分布自然，不同部位因接触环境不同锈色有差异。假锈（人工做锈）的特点：一是颜色单一，没有层次变化；二是锈浮于表面，用针挑或刀刮容易脱落；三是分布刻意不自然；四是可能有化学药水气味。另外老铜器还有包浆，是铜表面氧化的皮壳，温润有光泽。建议多看博物馆真品锈色培养感觉，新手从低价残器入门。您手上的铜器锈色什么样？',
         '铜器,锈色,真假辨别,包浆', '铜器锈色真伪鉴别方法', 85
  UNION ALL SELECT 'art_antique', '瓷器底足怎么看？底足能看出年代吗？',
         '您好，瓷器底足是鉴定和断代的重要部位，信息量很大。看底足几个方面：一看修胎方式，不同时代修足工艺有别，如元代粗犷、明代规整、清代精细；二看胎质，不同窑口和时代的胎质颜色和粗细有别；三看釉面，底足的釉面（如施釉到足端还是露胎）有时代特征；四看款识，底足上的年款是断代的重要依据，但也要警惕后加款；五看磨损和使用痕迹，老瓷器底足有自然磨损的磨痕，新仿做旧磨损不自然；六看火石红，部分老瓷器底足有自然的火石红（胎中氧化铁析出），新仿的火石红不自然。底足是辨伪的重点，建议购买时一定要求看底足图。您方便拍底足图吗？',
         '底足,瓷器,断代,修胎', '瓷器底足鉴定与断代要点', 87
  UNION ALL SELECT 'art_antique', '古玩市场能捡漏吗？怎么避免打眼？',
         '您好，"捡漏"是每个收藏者的梦想，但现实中捡漏的概率非常低。避免"打眼"（买到赝品）比捡漏更重要。给几点建议：一是调整心态，不要抱着捡漏的心态逛市场，贪便宜是上当的主要原因；二是量力而行，在自己熟悉的领域内购买，不碰不懂的东西；三是仔细验货，购买前仔细检查器物的各个细节，不要被表面迷惑；四是多方验证，高价器物请行家掌眼或科学检测；五是了解卖家，选择信誉好的商家，保留交易凭证；六是学会放弃，看不准就不买，机会永远有。记住"买的没有卖的精"，地摊上的"宝贝"大概率是故事。您有具体想买的东西吗？',
         '捡漏,打眼,购买技巧,风险', '古玩捡漏风险与防打眼建议', 88
  UNION ALL SELECT 'art_antique', '老家具的材质怎么判断？黄花梨紫檀怎么辨认？',
         '您好，老家具的材质鉴定是古典家具收藏的核心。黄花梨鉴别：一看纹理，黄花梨纹理流畅有"鬼脸"纹，木纹如行云流水；二看颜色，黄花梨颜色从浅黄到紫红，色泽温润有油性；三看密度，黄花梨沉于水或有坠手感；四闻气味，新切面有降香味。紫檀鉴别：一看颜色，紫檀新切面橘红色，久变深紫黑色；二看密度，紫檀沉于水，手感很沉；三看纹理，紫檀纹理细密有牛毛纹；四看划痕，紫檀在白纸上划有红褐色痕迹。材质鉴定难度大，建议新手请行家掌眼，或取木屑做科学检测。注意市场上冒充黄花梨的有白酸枝、紫檀柳等。您有家具图片吗？',
         '老家具,黄花梨,紫檀,材质鉴定', '老家具材质鉴别方法', 89
  UNION ALL SELECT 'art_antique', '古董买回来不想要了可以退吗？退换货规则是什么？',
         '您好，古董退换货比较特殊，因为古董交易有"货物售出概不退换"的行业惯例，但也要看具体情况：一是看平台规则，闲鱼上购买的古董，如果卖家承诺了退换政策则按承诺执行；二是看描述是否属实，如果收到的实物与描述严重不符（如真伪问题、品相问题未披露），可以申请退款退货；三是看是否有鉴定证据，如果购买后发现是赝品，需要有权威鉴定证据支持退款诉求；四是纯审美原因（不喜欢了但东西没问题），一般不支持退货。建议购买前确认退换政策，保留聊天记录，收到货先验货再确认收货。您是已经买了遇到问题吗？',
         '退换货,退款,规则,维权', '古董退换货规则与维权指南', 83
  UNION ALL SELECT 'art_antique', '古董邮寄安全吗？怎么包装运输才不会损坏？',
         '您好，古董邮寄确实风险较大，需要特别注意包装。包装建议：一是瓷器等易碎品，先用气泡膜多层包裹，器物之间用泡沫板隔开，放入坚固纸箱后用填充物填满空隙，箱外标注"易碎""小心轻放"；二是金属器物，用防潮材料包裹防止氧化，硬质外箱保护；三是书画等平面器物，用硬纸板夹板保护，装入硬纸筒；四是贵重古董建议保价，选择顺丰等靠谱快递，最好当面签收；五是要求卖家打包全程录像，拆包时也全程录像。建议高价古董尽量当面交易，邮寄风险不可控。您是买家还是卖家？我给更具体的包装建议。',
         '邮寄,包装,运输,安全', '古董邮寄包装安全指南', 85
  UNION ALL SELECT 'art_antique', '古董可以送拍卖吗？送拍有什么条件？',
         '您好，古董送拍是出手的好渠道，但有一定门槛。送拍流程：一是联系拍卖行征集部，发送器物照片和基本信息进行初审；二是初审通过后送实物到拍卖行鉴定；三是鉴定通过后签委托拍卖合同，确定估价和保留价；四是拍卖行制作图录，安排上拍；五是成交后扣除佣金（一般10%到15%）和其他费用后结算。送拍条件：一是器物要有一定价值，一般拍卖行有最低估价门槛（如嘉德保利通常5万以上）；二是品相完好来源清晰；三是最好有著录或传承记录。建议先了解各家拍卖行的征集方向和门槛，选择合适的拍卖行送拍。您的器物大概什么价值？',
         '拍卖,送拍,委托,条件', '古董送拍流程与条件', 86
  UNION ALL SELECT 'art_antique', '找人代购古董靠谱吗？代购有什么风险？',
         '您好，古董代购风险比较大，不建议新手尝试。代购的风险：一是真伪风险，代购人可能不懂鉴定，买到赝品后责任难界定；二是品相风险，代购人可能忽略品相细节，收到的器物与预期有差距；三是价格风险，代购人可能加价或拿回扣，实际购买价高于市场价；四是物流风险，代购后邮寄过程中损坏责任不清；五是售后风险，代购的古董出了问题很难追责。如果确实需要代购，建议：一是找信誉好的专业代购，最好有文博背景；二是明确代购费用和责任；三是要求全程视频沟通确认；四是保留所有交易记录。建议尽量自己上手购买。您有具体的代购需求吗？',
         '代购,风险,购买建议,信任', '古董代购的风险与注意事项', 82
  UNION ALL SELECT 'art_antique', '文房四宝有收藏价值吗？什么砚台值钱？',
         '您好，文房四宝（笔、墨、纸、砚）是古董收藏的重要门类，其中砚台收藏价值最高。值钱的砚台类型：一是名坑端砚，广东端溪老坑、麻子坑、坑仔岩等名坑砚石，石质细腻有石品（如鱼脑冻、蕉叶白、青花等）；二是歙砚，江西龙尾山歙砚，以眉纹、金星、水波纹等石品著称；三是名家制砚，有名家铭刻或制款的砚台价值更高；四是老坑旧坑石，已封坑的名坑砚石有稀缺性。收藏建议：一看石质石品，二看雕工，三看年代和传承，四看品相。注意市场上仿名坑砚石很多，建议从信誉好的商家购买，最好有石品高清图。您有具体的砚台想了解吗？',
         '文房四宝,砚台,端砚,歙砚', '文房四宝砚台收藏价值分析', 85
  UNION ALL SELECT 'art_antique', '老茶具有收藏价值吗？紫砂壶怎么辨别真假？',
         '您好，老茶具确实有收藏价值，紫砂壶是其中的热门门类。紫砂壶鉴别要点：一看泥料，真紫砂泥料有颗粒感和双层气孔结构，假紫砂多为添加化料的泥料；二看做工，老壶手工制作痕迹明显，内壁有接缝和推墙刮底痕迹，新壶模具成型内壁光滑；三看款识，名家壶的印章款识有个人风格，仿品款识呆板；四看包浆，老壶经长期使用有温润包浆，新壶做旧包浆不自然；五看出水孔，不同年代的出水孔形式有差异（如独孔、球孔、网孔）。收藏紫砂壶建议从当代工艺师的作品入门，逐步向老壶进阶。注意"化工壶"用化料调色有害健康。您有具体的壶想鉴定吗？',
         '紫砂壶,茶具,真假辨别,泥料', '紫砂壶鉴别与收藏建议', 87
  UNION ALL SELECT 'art_antique', '古董鉴定费一般多少？找谁鉴定比较靠谱？',
         '您好，古董鉴定的费用和渠道因器物和价值而异。鉴定渠道：一是国家文物部门或省级博物馆，部分提供鉴定服务，权威性高但预约难周期长；三是知名拍卖行，送拍鉴定免费但要求器物价值达标；三是专业鉴定机构，如古董鉴定中心，收费几百到几千不等；四是科学检测机构，碳14、热释光等检测，费用几千到上万；五是行家掌眼，找有经验的藏友或商家帮忙看，费用灵活但要防"走眼"。选择建议：高价器物建议科学检测加行家眼学双重验证；中低价器物找信誉好的行家掌眼即可。注意不要找"野鸡鉴定机构"，花钱买证书没有意义。您的器物大概什么价值？',
         '鉴定费,鉴定机构,权威,渠道', '古董鉴定渠道与费用参考', 84
  UNION ALL SELECT 'art_antique', '手里的古董想卖，去哪里出手比较好？',
         '您好，古董出手渠道有几个选择：一是闲鱼等二手平台，门槛低自己定价，但需要拍照描述和应对砍价，适合中低价器物；二是古玩市场门店，当面交易快速变现，但商家压价严重；三是送拍拍卖行，高价器物可能拍出好价，但周期长有佣金；四是藏友圈转让，通过微信群或论坛直接转让给藏友，成交快但需要信誉；五是寄卖，放在古玩店寄卖，省心但有寄卖费。建议根据器物价值选择：低价器物走闲鱼或藏友圈，中高价器物走拍卖行。出手前先估价了解市场行情，定价合理。建议保留购买凭证和传承记录，有助于成交。您的器物大概什么价值？',
         '出手,渠道,销售,拍卖', '古董出手渠道对比与建议', 86
  UNION ALL SELECT 'art_antique', '古董投资和股票房产比怎么样？值得投资吗？',
         '您好，古董投资与其他投资品种有本质区别，给您客观分析：优势方面，古董是实物资产有文化和艺术价值，长期看稀缺古董有增值潜力，且收藏过程有文化享受。劣势方面，一是流动性差，古董变现不如股票房产便捷，变现周期长；二是专业门槛高，需要丰富的鉴赏经验和市场认知，否则容易买到赝品；三是保管成本，古董需要专业保管条件，有损坏风险；四是市场波动，古董市场受经济环境和收藏热点影响，不是稳赚不赔。建议古董投资以收藏爱好为主，不要把主要资产投入古董，用闲钱收藏享受过程。您有具体想投资的方向吗？',
         '投资,股票,房产,风险', '古董投资与其他投资品种对比', 85
  UNION ALL SELECT 'art_antique', '古董怎么清洁？老物件能不能清洗？',
         '您好，古董清洁要非常谨慎，不当清洁会造成不可逆的损伤。清洁原则：一是能不清洁就不清洁，保持原样最安全，包浆和老化痕迹是岁月的证明也是鉴定依据；二是必须清洁时用最温和的方法，瓷器用软毛刷和温水轻擦，不要用化学清洁剂；三是金属器物不要自行除锈，有害锈找专业人士处理；四是书画不要自行清洁，交由专业修复师；五是木器用干软布轻擦，不要用水和化学剂。特别提醒：千万不要用酸碱清洁剂、超声波清洗机等强力清洁手段，会破坏包浆和表面。建议清洁前先咨询专业人士。您的古董是什么材质？什么情况需要清洁？',
         '清洁,清洗,保养,修复', '古董清洁的安全原则与方法', 82
  UNION ALL SELECT 'art_antique', '古董需要配底座吗？配座有什么讲究？',
         '您好，古董配座（底座）既是为了展示美观，也是为了保护器物。配座的讲究：一是材质选择，木质底座最常见，红木、紫檀等硬木显档次，且与古董气质相符；二是尺寸比例，底座要比器物底部略大，承重稳固，高度适中不要喧宾夺主；三是工艺风格，底座风格要与器物协调，传统器物配中式底座，工艺要精细；四是固定方式，器物放在底座上要稳固不晃动，但不要用胶水永久固定；五是定制与成品，高价或特殊形制的器物建议定制底座，普通器物买成品即可。好的底座能提升展示效果，也是对古董的保护。您是什么器物需要配座？',
         '配座,底座,展示,保养', '古董配座的讲究与建议', 78
  UNION ALL SELECT 'art_antique', '古董破损了可以修补吗？修补后影响价值吗？',
         '您好，古董破损可以修补，修补方式和对价值的影响因方法和器物而异。修补方式：一是传统锔瓷，用铜钉或银钉锔合裂纹，有历史感和工艺美感，老锔瓷本身就是文物；二是金缮，用大漆粘合裂缝后敷金粉，修复痕迹变成装饰，有艺术美感；三是无痕修复，用专业材料修复到肉眼难辨，适合展示但会降低收藏价值；四是胶水粘合，最简单但最不专业，影响品相。对价值的影响：好的修复（金缮、锔瓷）可能增加艺术价值，劣质修复（胶水）会降低价值。建议珍贵器物找专业修复师操作，保留修复前的照片记录。您的器物破损严重吗？',
         '修补,修复,金缮,锔瓷', '古董破损修复方式与价值影响', 84
  UNION ALL SELECT 'art_antique', '买古董带收藏证书有用吗？收藏证书怎么看？',
         '您好，古董收藏证书的价值要分别看待，不是所有证书都有用。证书的可靠性看几个方面：一是发证机构，文物部门、博物馆、知名拍卖行出具的证书有公信力，一些商业机构的证书花钱就能办意义不大；二是证书内容，好的证书应包含器物描述、鉴定结论、鉴定方法、鉴定人资质等信息；三是防伪措施，正规证书有编号、钢印、防伪标识等。需要注意的是，古董鉴定没有百分百准确，证书只是参考。建议：一是证书作为参考不要迷信；二是高价古董多家鉴定交叉验证；三是了解发证机构的信誉。您的证书是什么机构发的？',
         '收藏证书,鉴定,机构,可信度', '古董收藏证书的价值与鉴别', 81
  UNION ALL SELECT 'art_antique', '怎么判断古董是老的还是现代仿的？',
         '您好，判断古董新老（真伪）是收藏的核心技能，综合几个方面：一看包浆，老器物有自然形成的包浆和老化痕迹，温润有层次，新仿做旧包浆不自然；二看工艺，老器物手工制作有自然的手工痕迹，新仿多为机器加工或模具成型；三看材质，不同年代使用的材质有区别，如老瓷器胎釉配方有时代特征；四看磨损，老器物有自然磨损和使用痕迹，分布合理，新仿做旧磨损刻意不自然；五看细节，老器物在细节处（如底足、边角、内壁）有岁月痕迹，新仿往往只做表面功夫。建议多看真品多上手，培养对"老气"的感觉。您有具体的器物需要鉴定吗？',
         '新老鉴别,真伪,包浆,工艺', '古董新老真伪综合鉴别方法', 88
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;


-- ============================================================
-- 4. 潮玩手办 (art_trendy) - 30条
-- ============================================================
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.58', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'art_trendy' AS code, '这个潮玩是正品吗？怎么辨别真假？' AS question,
         '您好，潮玩真假鉴别是二手交易中最常见的问题，给您几个通用鉴别要点：一是看包装，正品包装印刷清晰色彩准确，有防伪标签或镭射标，假货包装常有套色不准、纸张廉价的问题；二是看做工，正品注塑精细无毛刺，涂装均匀色彩还原，假货常有毛刺、溢色、涂装不均；三是看材质，正品用环保PVC/ABS材质有特定手感，假货材质廉价有刺鼻气味；四是看细节，正品的面部表情、衣纹细节清晰锐利，假货模糊粗糙；五是查编号，限量款有唯一编号可在官网验证。建议购买前要求卖家拍包装、底部标识、面部细节的高清图。您看中的是什么品牌？' AS answer,
         '真假辨别,潮玩,正品,鉴别' AS tags, '潮玩真假通用鉴别方法' AS source_summary, 89 AS score
  UNION ALL SELECT 'art_trendy', '手办的品相怎么判断？什么样的品相好？',
         '您好，手办品相主要从几个方面判断：一是盒况，全新未拆封（MIB）的盒子完好无挤压变形为最佳，有压痕破损的品相下降；二是盒内状况，未拆封状态下手办无涂装问题、无零件松动或脱落；三是已拆封的看手办本身，涂装完好无掉漆、无色差、零件齐全无断裂、底座完好；四是透明件（如有）无发黄雾化。品相分级大致：全新未拆封MIB最好，已拆封未展示品相好，已展示有轻微灰尘品相中等，有损伤掉漆品相差。二手手办价格与品相直接挂钩，建议购买时要求卖家拍清各部位细节。您看中的手办是全新还是二手？',
         '品相,盒况,涂装,零件', '手办品相判断标准与分级', 86
  UNION ALL SELECT 'art_trendy', '手办带不带原盒价格差多少？无盒的值得买吗？',
         '您好，手办原盒对价格影响确实较大。带原盒的价格通常比无盒贵20%到40%，限量款和热门款差价更大，因为原盒是完整收藏的一部分，也是品相保护的载体。无盒手办值不值得买要看目的：如果是为了展示和把玩，无盒不影响手办本身的观赏，且价格更实惠，值得买；如果是为了收藏保值或未来转手，原盒很重要，缺盒会影响出手价格和买家意愿。购买无盒手办注意：一是确认手办本身品相完好，二是确认配件齐全（底座、替换手、小配件等），三是价格要反映无盒的折扣。建议收藏向的优先买带盒的。您是展示还是收藏？',
         '原盒,无盒,价格差,购买建议', '手办原盒对价格的影响分析', 83
  UNION ALL SELECT 'art_trendy', '限量版手办值得入手吗？升值空间大吗？',
         '您好，限量版手办确实有一定升值空间，但不是所有限量款都能升值。升值潜力大的几个特征：一是品牌效应，知名IP和热门品牌的限量款更受市场追捧，如Pop Mart、Medicom Toy等；二是限量数量，发行量越少越稀缺，编号越小越值钱；三是热门IP，如漫威、迪士尼、初音未来等大IP的限量款关注度更高；四是艺术家款，知名设计师联名款有艺术收藏价值；五是品相，全新未拆封的升值空间大，已拆封的升值有限。建议入手限量款以喜欢为主、升值为辅，不要抱着投资心态炒潮玩。您看中的是什么限量款？',
         '限量版,升值,收藏价值,投资', '限量版手办升值空间分析', 87
  UNION ALL SELECT 'art_trendy', '盲盒隐藏款概率多少？隐藏款值钱吗？',
         '您好，盲盒隐藏款是盲盒玩法中最有吸引力的部分。隐藏款概率通常在1/72到1/144之间，即每72到144个常规款中出现一个隐藏款，具体概率因系列而异。隐藏款值不值钱看几个因素：一是系列热度，热门IP和热门系列的隐藏款市场价远高于常规款，如Pop Lab热门系列隐藏款可能炒到几百上千元；二是概率稀有度，概率越低的隐藏款越值钱；三是品相，全新未拆封的隐藏款最值钱；四是市场热度，刚发售时热度高价格高，后续可能回落。建议理性对待盲盒，不要为了隐藏款大量购买，二手直接买隐藏款可能更划算。您看中的是哪个系列的隐藏款？',
         '盲盒,隐藏款,概率,市场价', '盲盒隐藏款概率与价值分析', 85
  UNION ALL SELECT 'art_trendy', '手办未拆封和已拆封价格差多少？买哪个好？',
         '您好，手办未拆封（MIB）和已拆封的价格差异取决于品牌、热度和品相。一般未拆封比已拆封贵10%到30%，热门限量款差价更大。买哪个好要看目的：如果是为了收藏保值或转手，未拆封最佳，品相有保障且市场认可度高；如果是为了展示欣赏，已拆封更实惠，且手办本身就是用来欣赏的；如果是为了把玩拍照，已拆封是必选项。购买已拆封手办注意：一是确认手办品相完好无损伤，二是确认配件齐全，三是确认是正品（已拆封无法靠包装辨别）。购买未拆封手办注意：一是确认包装完好无拆痕，二是确认不是退换货二次封装。您是收藏还是展示？',
         '未拆封,已拆封,价格差,购买建议', '手办未拆封与已拆封对比', 84
  UNION ALL SELECT 'art_trendy', 'Pop Mart泡泡玛特的价格怎么定？二手行情怎么看？',
         '您好，Pop Mart泡泡玛特的二手行情波动较大，定价参考几个因素：一是系列和IP，热门IP如Molly、Dimoo、Skullpanda的行情好于冷门系列；二是款式稀有度，隐藏款和限量款远高于常规款；三是品相，全新未拆封最贵，已拆封品相好的次之；四是热度时效，刚发售时热度高价格高，后续可能回落也可能因断货上涨。查看行情的渠道：一是闲鱼搜索同款看出价和成交价，二是千岛等潮玩交易平台查参考价，三是微信群和论坛了解藏友出价。建议购买前多平台比价，定价时参考同类成交价留一定议价空间。您有具体的款式想了解吗？',
         'Pop Mart,泡泡玛特,定价,行情', '泡泡玛特二手行情与定价参考', 86
  UNION ALL SELECT 'art_trendy', '手办有收藏价值吗？长期收藏保值吗？',
         '您好，手办的收藏价值因品牌和款式而异。有收藏价值的手办特征：一是知名IP，如高达、初音未来、漫威等大IP有持续粉丝群体；二是知名品牌，如Good Smile Company、Medicom Toy等品牌品质有保障；三是限量款，发行量少的限量款有稀缺性；四是艺术家联名款，知名设计师的作品有艺术收藏价值；五是品相，全新未拆封带原盒的保值好。保值方面，热门限量款长期看有增值可能，但常规款通常会贬值，因为市场供给充足。建议以喜欢为主收藏，不要抱着投资心态，潮玩市场波动大。您收藏的是什么方向？',
         '收藏价值,保值,手办,投资', '手办收藏价值与保值分析', 85
  UNION ALL SELECT 'art_trendy', '手办怎么保养？怕晒怕灰吗？',
         '您好，手办保养很重要，保养不当会发黄掉色。保养要点：一是防尘，手办摆放建议放在展示柜中，长期不展示的用亚克力防尘盒收纳，定期用软毛刷或气吹清理灰尘；二是避光，紫外线会使手办发黄褪色，避免阳光直射，展示柜建议用防紫外线玻璃；三是防潮，潮湿环境会导致手办涂装起泡或金属件生锈，保持存放环境干燥；四是防高温，高温会使PVC变形，避免放在暖气或热源附近；五是轻拿轻放，手办零件脆弱，更换姿势时要小心；六是不要用化学清洁剂，用干软布或软毛刷清洁。建议贵重手办用亚克力盒单独保护。您的手办是怎么展示的？',
         '保养,防尘,避光,防潮', '手办保养防尘防光要点', 88
  UNION ALL SELECT 'art_trendy', '手办涂装有色差正常吗？有色差是不是假货？',
         '您好，手办涂装存在色差是比较常见的情况，不一定代表假货。色差的原因：一是官方批次差异，同一款手办不同生产批次的涂装可能略有差异，这是正常的生产品控范围；二是手工涂装差异，部分高端手办有手工涂装环节，每件略有不同；三是光照和拍摄差异，不同光线条件下颜色看起来不同。假货的涂装问题通常更严重：大面积溢色、颜色完全不对、涂装粗糙不均匀等。判断方法：对比官方宣传图和正品实拍图，如果颜色大致一致只有细微差异是正常的，如果颜色明显不对则可能是假货。您方便发图对比一下吗？',
         '色差,涂装,真假辨别,品控', '手办涂装色差的原因与鉴别', 82
  UNION ALL SELECT 'art_trendy', '限量版手办的编号怎么看？编号小的是不是更值钱？',
         '您好，限量版手办的编号是限量身份的标识，通常印在底座底部或包装上，格式如"001/500"表示这是500个限量中的第1号。编号对价值的影响：一是编号大小，编号越小越值钱，特别是001号和最后一个编号有特殊收藏意义；二是限量总数，总量越少越稀缺越值钱；三是编号位置，底座刻编号比贴纸编号更有档次。收藏建议：编号小的限量款有更好的保值和增值空间，但溢价也更高。购买限量款注意：一是确认编号真实（不是后刻的），二是确认限量总数与官方信息一致，三是保留限量证书。您的限量款是什么编号？',
         '限量编号,编号,限量版,收藏价值', '限量版手办编号的意义与价值', 83
  UNION ALL SELECT 'art_trendy', '手办的涂装质量怎么看？怎么判断涂装好不好？',
         '您好，手办涂装质量是判断手办品质的重要指标。好的涂装标准：一是色彩还原，颜色与官方设定一致，饱和度和明暗准确；二是涂装精度，分色干净利落，线条清晰无溢色，细节处涂装到位；三是涂装均匀，大面积色彩均匀无色差无颗粒感；四是层次感，阴影和高光处理到位，有立体感；五是保护漆，表面有哑光或亮光保护漆，均匀无滴痕。涂装不好的表现：溢色（颜色超出分色线）、漏涂（应该有色的地方没涂到）、颗粒（涂装表面有颗粒突起）、色差（颜色与设定不符）。建议购买前看实物图或评测，不要只看官方宣传图。您有具体的手办想评估吗？',
         '涂装,质量,品相,鉴别', '手办涂装质量判断标准', 84
  UNION ALL SELECT 'art_trendy', '潮玩二手价怎么定？卖出怎么定价合理？',
         '您好，潮玩二手定价需要参考多个因素。定价步骤：一是查询行情，在闲鱼搜索同款看出价区间和近期成交价，在千岛等平台查参考价；二是评估品相，全新未拆封定价最高，已拆封品相好的次之，有瑕疵的相应降价；三是考虑热度，热门款和断货款可以溢价，冷门款需要折价；四是留议价空间，定价时比心理价位高10%到20%，给买家砍价空间。定价策略：急出就定市场低价，不急可以定中等价位等有缘人。建议详细描述品相，多拍高清图，标明是否有原盒和配件，这样更容易成交。您想出的是什么款式？',
         '二手价,定价,出售,行情', '潮玩二手定价策略与参考', 85
  UNION ALL SELECT 'art_trendy', '手办的盒况重要吗？盒子有压痕影响价值吗？',
         '您好，手办盒况对价值有一定影响，特别是收藏向的手办。盒况影响程度：一是品牌和热度，热门限量款的盒况影响大，盒子有压痕可能贬值10%到20%；二是品相定位，全新未拆封（MIB）的盒子是品相的一部分，盒子有损就不是"全品"了；三是收藏目的，收藏向买家对盒况要求高，展示向买家对盒况要求低。盒况分级：全新盒无压痕无破损为最佳，有轻微压痕为中等，有明显破损为差。建议购买时要求卖家拍盒况图，特别是边角部位。如果盒子完好建议保留，展示时也不要丢弃。您的手办盒子是什么状况？',
         '盒况,压痕,品相,收藏价值', '手办盒况对价值的影响评估', 81
  UNION ALL SELECT 'art_trendy', '限定款手办哪里能买到？错过的限定款怎么办？',
         '您好，限定款手办的购买渠道和补救方法。限定款购买渠道：一是官方渠道，品牌官网或线下旗舰店发售，最可靠但竞争激烈需要抢购；二是展会限定，如Wonder Festival、CCG等展会的限定款，需要去现场购买或找代购；三是海外代理，部分限定款在海外零售商发售，可通过海淘或代购购买；四是二手市场，闲鱼、千岛等平台有藏友转手，价格通常比原价高。错过限定款的补救：一是二手市场购买，接受溢价；三是关注品牌后续是否再版（限定款通常不再版，但部分会出通版）；三是找可信赖的代购。建议限定款发售时尽早关注抢购。您想买哪个限定款？',
         '限定款,购买渠道,代购,二手', '限定款手办购买渠道与补救方法', 84
  UNION ALL SELECT 'art_trendy', '潮玩可以转手赚钱吗？怎么投资潮玩？',
         '您好，潮玩转手赚钱是可能的，但需要眼光和时机，不是所有潮玩都能升值。赚钱的潮玩特征：一是限量款，发行量少的限量款有稀缺性；二是热门IP，大IP的限定款市场关注度高；三是断货款，官方售罄后二手价格上涨；四是艺术家款，知名设计师联名款有收藏价值。投资建议：一是低价买入，在官方发售时原价购入，等断货后溢价出售；二是品相要好，全新未拆封带盒的保值好；三是选对款式，热门限量款才有升值空间，常规款通常贬值；四是时机把握，刚断货时溢价最高，但长期看可能回落也可能继续涨。建议以收藏心态入手，不要纯投资。您有想投资的款式吗？',
         '转手,投资,升值,潮玩', '潮玩投资与转手策略分析', 86
  UNION ALL SELECT 'art_trendy', '手办快递包装怎么才安全？怕运输损坏。',
         '您好，手办快递包装很重要，运输损坏是二手手办交易中最常见的纠纷。包装建议：一是未拆封手办，先用气泡膜包裹盒身防止盒况损坏，放入合适大小的纸箱用填充物填满空隙；二是已拆封手办，先用气泡膜包裹手办本体，零件分开包装防止互相碰撞，底座单独包裹，放入纸箱用泡沫填充；三是贵重手办建议用双层纸箱，内箱和外箱之间用缓冲材料；四是箱外标注"易碎品""小心轻放""勿压"；五是选择靠谱快递（建议顺丰），保价运输；六是提醒卖家打包全程录像，买家收货时先验货再签收。您是买家还是卖家？',
         '快递,包装,运输,安全', '手办快递包装安全指南', 85
  UNION ALL SELECT 'art_trendy', '展会上买的限定款手办怎么验真假？',
         '您好，展会限定款手办的验真有几个方法：一是核对官方信息，对比品牌官方公布的限定款信息，包括款式、编号、发售数量等；二是查看防伪标识，正规限定款通常有防伪标签、镭射标或唯一编号，可在官网验证；三是检查做工品质，正品的做工和涂装质量有保障，假货做工粗糙；四是保留购买凭证，展会购买的收据或小票是来源证明；五是对比正品实拍图，与已确认正品的实拍图对比细节。如果是从二手市场购买的展会限定款，要特别注意假货风险，建议选择信誉好的卖家，保留交易记录。您有具体的限定款想验证吗？',
         '展会限定,验真,防伪,真假辨别', '展会限定款手办验真方法', 83
  UNION ALL SELECT 'art_trendy', '联名款手办值不值得买？联名款有什么特别的？',
         '您好，联名款手办是两个或多个品牌/IP合作推出的特别款，确实有一定收藏价值。联名款的特别之处：一是独特设计，联名款通常有独特的设计元素，融合合作品牌的特色，与通版不同；二是限量发行，联名款多为限量发售，有稀缺性；三是收藏意义，联名款代表品牌合作，有特殊纪念意义。值不值得买看几个因素：一是IP组合，两个热门IP的联名更有收藏价值；二是限量数量，发行量少的更有价值；三是设计独特性，设计越独特越受欢迎；四是个人喜好，喜欢就值得买。建议联名款发售后尽快入手，断货后溢价较高。您看中的是什么联名款？',
         '联名款,限定,收藏价值,IP', '联名款手办的价值与选择', 82
  UNION ALL SELECT 'art_trendy', '潮玩被炒作价格虚高吗？怎么判断合理价位？',
         '您好，潮玩市场确实存在炒作现象，部分热门款价格虚高。判断合理价位的方法：一是参考原价，官方发售原价是基准，二手价在原价基础上波动是正常的，但高出原价数倍甚至数十倍就要警惕；二是看供需关系，真正因断货稀缺而涨价的款式有支撑，纯炒作拉高的价格泡沫大；三是关注市场情绪，社交媒体上热度暴涨时价格可能被炒高，热度退去后价格回落；四是对比历史成交价，看价格走势是稳步上涨还是突然暴涨。建议理性购买，不要在价格高点追涨，等待热度回落或选择替代款。您看中的款式现在什么价位？',
         '炒作,虚高,合理价位,行情', '潮玩炒作与合理价位判断', 85
  UNION ALL SELECT 'art_trendy', '手办开模是什么意思？开模手办是假货吗？',
         '您好，"开模"在潮玩圈有两种含义，要区分来看。一是官方开模，品牌方为生产手办制作模具，这是正规生产流程；二是盗版开模，山寨厂家仿造正品手办翻制模具生产的假货。盗版开模手办就是假货，鉴别方法：一是看做工，盗版开模手办注塑粗糙有毛刺，涂装质量差，细节模糊；二是看材质，盗版用廉价材料可能有刺鼻气味；三是看包装，盗版包装印刷质量差或无包装；四是看价格，远低于正品原价的大概率是盗版。建议新手从官方渠道或信誉好的二手卖家购买，不要贪便宜买来路不明的低价"开模"手办。您有具体的手办想验证吗？',
         '开模,盗版,假货,真假辨别', '手办开模的含义与盗版鉴别', 83
  UNION ALL SELECT 'art_trendy', '潮玩怎么防尘保养？展示柜有讲究吗？',
         '您好，潮玩防尘保养很重要，直接影响手办的品相和保值。防尘方案：一是亚克力防尘盒，单个手办套亚克力盒是最佳方案，密封性好且美观，但成本较高；二是展示柜，带玻璃门的展示柜可以防尘，比开放式搁板好很多；三是防尘罩，用透明防尘罩覆盖，经济实惠但美观度一般。保养补充：定期用软毛刷或相机气吹清理灰尘，不要用湿布擦拭以免留下水渍；展示柜内可放干燥剂防潮；避免阳光直射防止发黄褪色。建议贵重手办用亚克力盒单独保护，一般手办放带门展示柜。您的手办目前是怎么展示的？',
         '防尘,保养,展示柜,亚克力盒', '潮玩防尘保养与展示方案', 85
  UNION ALL SELECT 'art_trendy', '手办零件断了能修复吗？怎么修补手办？',
         '您好，手办零件断裂是可以修复的，修复方法取决于断裂情况。修复方案：一是轻微断裂，用模型专用胶水（如田宫溜缝胶）粘合，粘合后用砂纸打磨平整再补色；二是断裂处有缺口，用AB补土填补缺口，固化后打磨修型再补色；三是关节松动，用透明指甲油或502胶水涂在关节处增加阻尼；四是涂装掉漆，用模型颜料补色后喷保护漆。修复注意事项：一是修复前拍照记录原始状态；二是用模型专用工具和材料，不要用普通胶水；三是补色要尽量匹配原色；四是修复技术不熟练建议找专业修复师。建议小心把玩避免损坏。您手办是什么部位断了？',
         '修复,修补,断裂,零件', '手办零件断裂修复方法', 82
  UNION ALL SELECT 'art_trendy', '限定款手办带证书吗？证书怎么看真假？',
         '您好，限定款手办通常附带限量证书，证书是限量身份的证明。证书包含的信息：限量编号、限量总数、品牌信息、产品名称等。证书验真方法：一是核对官方信息，对比品牌官网公布的限定款信息是否一致；二是查看防伪措施，正规证书有防伪标签、镭射标或唯一验证码；三是检查印刷质量，真证书印刷精美纸张有质感，假证书印刷粗糙；四是官网验证，部分品牌支持官网输入编号验证。建议购买限定款时要求卖家提供证书照片，确认编号与手办底座编号一致。无证书的限定款价格要打折。您的限定款有证书吗？',
         '限定款,证书,防伪,验真', '限定款手办证书验真方法', 84
  UNION ALL SELECT 'art_trendy', '潮玩套装值得买吗？套装比单买划算吗？',
         '您好，潮玩套装是否值得买要看具体情况。套装的优势：一是价格优惠，套装通常比单买总价便宜10%到20%；二是完整性好，套装能获得全套款式，包括隐藏款；三是收藏价值，完整套装比散款更有收藏价值，出手时也更受欢迎。套装的劣势：一是总价高，一次性投入大；二是可能有不喜欢的款式，套装中的款式无法挑选；三是盲盒套装有随机性。建议：如果喜欢整个系列且预算充足，套装更划算；如果只喜欢个别款式，单买更合适。购买套装注意确认是否为官方原装套装，有些卖家自组的"套装"不是官方套装。您看中的是什么套装？',
         '套装,单买,划算,收藏价值', '潮玩套装与单买对比分析', 81
  UNION ALL SELECT 'art_trendy', '手办买回来不满意可以退货吗？退货条件是什么？',
         '您好，手办退货要看具体情况和卖家政策。退货条件：一是未拆封手办，如果卖家承诺了七天无理由退货且包装完好，一般可以退货；二是已拆封手办，如果与描述严重不符（如假货、品相问题未披露、配件缺失），可以申请退款退货；三是如果只是不喜欢但手办没问题且已拆封，一般不支持退货，因为拆封后影响二次销售。建议购买前确认退货政策，收到货先验货再拆封，发现问题不要拆封直接联系卖家。保留聊天记录和开箱视频作为证据。闲鱼平台一般支持描述不符的退货申请。您是遇到退货问题了吗？',
         '退货,退款,条件,维权', '手办退货条件与维权指南', 83
  UNION ALL SELECT 'art_trendy', '潮玩新品怎么预订？预订有什么注意事项？',
         '您好，潮玩新品预订是确保拿到热门款的好方式。预订渠道：一是官方渠道，品牌官网或旗舰店的预订页面，最可靠；二是线下门店，Pop Mart等品牌的线下门店接受预订；三是代购，部分海外限定款需要找代购预订。预订注意事项：一是确认预订时间，热门款需要抢购，提前关注发售信息；二是了解定金政策，预订一般需要付定金，确认定金是否可退；三是确认发货时间，预订到发货可能有数月间隔；四是选择可靠渠道，避免被骗定金；五是保留预订凭证。建议关注品牌官方社交媒体获取发售信息。您想预订什么款式？',
         '预订,新品,抢购,注意事项', '潮玩新品预订渠道与注意事项', 82
  UNION ALL SELECT 'art_trendy', '手办晒单是什么意思？晒单有什么用？',
         '您好，"晒单"是潮玩圈的术语，指买家收到手办后在社交媒体或论坛上分享开箱照片和心得。晒单的作用：一是分享喜悦，与同好交流收藏乐趣；二是参考价值，晒单照片是其他买家了解实物的重要参考，比官方宣传图更真实；三是建立信誉，经常晒单的玩家在圈内有一定影响力，二手交易时更受信任；四是社交互动，通过晒单结识同好，交流收藏心得。建议购买手办后可以拍照晒单，分享开箱体验，既是记录也是交流。晒单时注意拍清细节，客观评价优缺点。您是想知道哪里可以晒单吗？',
         '晒单,开箱,社交,评价', '潮玩晒单的意义与作用', 78
  UNION ALL SELECT 'art_trendy', '现在潮玩市场行情怎么样？还能赚钱吗？',
         '您好，潮玩市场近年经历了从火爆到回归理性的过程。行情分析：一是头部品牌依然强势，Pop Mart、Medicom Toy等知名品牌的热门款仍有市场；二是炒作退潮，前几年被爆炒的款式价格回落，市场更理性；三是分化明显，真正稀缺的限量款保值增值，大量生产的常规款贬值；四是评级潮玩兴起，高分评级手办有溢价。还能不能赚钱：能，但需要眼光和时机，低价买入热门限量款等断货后溢价出售。建议以收藏爱好为主，不要纯投资炒潮玩，市场波动大风险高。您有具体想了解的款式吗？',
         '行情,市场,赚钱,投资', '潮玩市场行情与投资分析', 86
  UNION ALL SELECT 'art_trendy', '手办砍价有什么技巧？怎么和卖家谈价格？',
         '您好，闲鱼上买手办砍价有几个实用技巧。砍价技巧：一是做足功课，了解同款市场行情，用成交价作为砍价依据；二是找合理理由，如盒况有压痕、已拆封、配件缺失等品相问题，有理有据地谈；三是表达诚意，说明自己真心想买、爽快付款，让卖家愿意让步；四是出价合理，一般从八折左右开始谈，不要太低让卖家反感；五是打包购买，如果卖家有多款手办，可以打包谈总价更优惠；六是适时收手，价格合理就成交，不要死缠烂打。建议选择支持验货的卖家，收到货确认品相后再确认收货。您看中的是什么手办？',
         '砍价,议价,技巧,购买', '手办砍价技巧与议价策略', 83
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;


-- ============================================================
-- 5. 纪念品 (art_memorabilia) - 30条
-- ============================================================
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.58', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'art_memorabilia' AS code, '纪念币怎么辨别真假？有证书就是真的吗？' AS question,
         '您好，纪念币鉴别是纪念品收藏的重要技能。辨别要点：一看材质重量，真纪念币用贵金属的重量和密度有标准，可用电子秤称重对比；二看工艺，真币压力足图文清晰深峻，假币图文发软模糊；三看齿边，真币齿边均匀规整，假币粗糙；四看包装，真纪念币有官方原装包装和证书，假币包装印刷质量差。有证书不等于真品，证书也可能造假，要综合判断。建议购买纪念币选择银行或正规渠道，保留购买凭证。贵金属纪念币可送评级机构鉴定。您有具体的纪念币想鉴定吗？' AS answer,
         '真假辨别,纪念币,证书,鉴定' AS tags, '纪念币真伪鉴别方法' AS source_summary, 88 AS score
  UNION ALL SELECT 'art_memorabilia', '纪念章品相怎么判断？什么样的品相好？',
         '您好，纪念章品相主要看几个方面：一是表面无划痕无磕碰，镜面章的镜面光亮无瑕疵，喷砂章的喷砂均匀无脱落；二是无氧化变色，金属章氧化后会出现色斑影响美观和价值；三是包装完好，原装包装和证书齐全的品相最好；四是边缘无磨损，齿边或光边完好无变形。品相对纪念章价值影响很大，全品相的比有瑕疵的贵20%到50%。建议购买时要求卖家拍高清细节图，特别是表面和边缘。保存时用原装盒或亚克力盒保护，避免触摸表面。您的纪念章是什么品相？',
         '品相,纪念章,氧化,包装', '纪念章品相判断标准', 84
  UNION ALL SELECT 'art_memorabilia', '奥运纪念品有收藏价值吗？升值空间大吗？',
         '您好，奥运纪念品的收藏价值因品种而异。有收藏价值的类型：一是贵金属纪念币，金银纪念币本身有贵金属价值托底，且奥运题材有纪念意义；二是官方授权限量品，如奥运火炬模型、吉祥物限量版等发行量少的品种；三是热门奥运会的纪念品，如北京2008奥运会的纪念品关注度最高。升值空间分析：北京2008奥运金银币系列近年有不错涨幅，普通材质纪念品升值有限。建议收藏以纪念意义为主，选择官方发行渠道购买，保留证书和包装。注意区分官方发行品和普通商业纪念品，后者收藏价值低。您有具体的奥运纪念品吗？',
         '奥运,纪念品,收藏价值,升值', '奥运纪念品收藏价值分析', 86
  UNION ALL SELECT 'art_memorabilia', '纪念邮票和普通邮票有什么区别？值钱吗？',
         '您好，纪念邮票是为纪念重大事件或人物而专门发行的邮票，与普通邮票的区别：一是发行目的，纪念邮票为纪念特定事件发行，有纪念意义；二是设计精美，纪念邮票通常设计更加精美，题材丰富；三是发行量，纪念邮票发行量通常比普通邮票少。值不值钱看几个因素：一是发行年代，早期纪念票存世量少价值高；二是发行量，发行量少的更值钱；三是品相，全新原胶全品最贵；四是题材热度，热门题材如生肖、伟人等关注度高。建议从系列收藏入手，如生肖系列、建国系列等。您有具体的纪念邮票吗？',
         '纪念邮票,普通邮票,区别,价值', '纪念邮票的特点与价值分析', 83
  UNION ALL SELECT 'art_memorabilia', '签名纪念品怎么验真？签名是真的就值钱吗？',
         '您好，签名纪念品的验真是收藏中的难点。验真方法：一是对比已知真迹签名，与官方确认的签名样本对比笔迹特征；二是看签名工具和墨迹，不同年代用的笔和墨水有差异；三是看签名载体，签名在官方商品、照片、球衣等上的可信度高于在白纸上；四是看来源证明，有购买凭证或见证人签名的更可信；五是专业鉴定，可送PSA、JSA等专业签名鉴定机构。签名是真的就值钱吗：不一定，价值还取决于签名者的知名度、签名物品的稀缺性、签名的清晰度等。建议购买高价签名品选择有鉴定证书的。您有什么签名纪念品？',
         '签名,验真,鉴定,收藏价值', '签名纪念品验真与价值评估', 85
  UNION ALL SELECT 'art_memorabilia', '纪念品有证书但没发票，能买吗？',
         '您好，纪念品有证书没发票是比较常见的情况，能不能买要看具体品种。证书和发票的作用：证书是产品身份的证明（如限量编号、发行信息），发票是购买凭证（证明来源和价格）。有证书说明产品本身是正品，没发票可能是个人转让或赠品转手。购买建议：一是核对证书信息与实物是否一致；二是检查证书的防伪措施；三是了解发行渠道判断合理性；四是保留交易记录。如果是贵金属纪念币等高价品，建议选择有发票的卖家或银行渠道购买。如果是中低价纪念品，有证书且信息核验无误可以买。您看中的是什么纪念品？',
         '证书,发票,购买建议,来源', '纪念品有证书无发票的购买建议', 82
  UNION ALL SELECT 'art_memorabilia', '纪念品原装包装重要吗？无包装影响价值吗？',
         '您好，纪念品原装包装对价值有一定影响，特别是限量发行品。原装包装的重要性：一是品相保护，原装盒是为产品量身设计的保护容器；二是完整收藏，限量品的原装盒和证书是完整收藏的一部分；三是来源证明，原装包装能佐证产品的真实性。无包装对价值的影响：限量纪念币无原装盒可能贬值10%到20%，普通纪念品影响较小。建议购买时优先选择带原装包装的，保存时不要丢弃包装。如果只有无包装的，价格要相应低一些。您的纪念品有原装包装吗？',
         '原装,包装,价值,收藏', '纪念品原装包装的重要性', 80
  UNION ALL SELECT 'art_memorabilia', '世博会纪念品值钱吗？什么世博纪念品有收藏价值？',
         '您好，世博会纪念品的收藏价值因品种和届次而异。有收藏价值的类型：一是贵金属纪念币，世博金银币有贵金属价值托底且有纪念意义；二是限量纪念品，如世博护照、吉祥物限量版等发行量少的品种；三是热门世博会的纪念品，如2010年上海世博会的纪念品关注度最高。上海世博会纪念品近年市场表现：金银币系列有稳定增值，普通材质纪念品升值有限。建议收藏以纪念意义为主，选择官方发行渠道购买，保留证书和包装。注意区分官方发行品和普通商业纪念品。您有具体的世博纪念品吗？',
         '世博,纪念品,收藏价值,升值', '世博会纪念品收藏价值分析', 83
  UNION ALL SELECT 'art_memorabilia', '体育赛事纪念品怎么选？哪种最保值？',
         '您好，体育赛事纪念品的收藏价值因赛事和品种而异。最保值的类型：一是贵金属纪念币，奥运、世界杯等大赛金银币有贵金属价值托底且发行量少；二是官方授权限量品，如吉祥物限量版、火炬模型等发行量少的品种；三是签名纪念品，明星运动员签名的球鞋、球衣等有粉丝群体支撑。选择建议：一是选大赛事，奥运会、世界杯等国际大赛的纪念品关注度高；二是选官方发行，避免商业仿制品；三是选限量品，发行量少的更保值；四是保留证书和包装。注意体育纪念品市场受赛事热度影响大，赛事结束后热度可能下降。您有具体的体育纪念品吗？',
         '体育,赛事,纪念品,保值', '体育赛事纪念品选择与保值分析', 84
  UNION ALL SELECT 'art_memorabilia', '名人签名怎么辨别真假？签在什么上面最值钱？',
         '您好，名人签名辨假是收藏的重要技能。辨假方法：一是对比真迹样本，与官方确认的签名对比笔迹特征，包括笔画走势、力度、连贯性等；二是看墨迹，真签名的墨迹有自然渗透和干燥痕迹，印刷签名则平面均匀；三是看载体，签名在官方商品、照片、球衣等特定物品上比白纸可信度高；四是看来源，有现场签名照片或视频佐证的最可信；五是专业鉴定，可送PSA、JSA等机构鉴定。最值钱的签名载体：一是签名在代表性物品上（如球星签名在球衣上）；二是签名照片有合影；三是限量签名编号品。建议购买高价签名品选择有鉴定证书的。您有什么签名纪念品？',
         '签名,辨假,载体,收藏价值', '名人签名辨假与价值分析', 86
  UNION ALL SELECT 'art_memorabilia', '纪念品的出处和来历重要吗？怎么看来源？',
         '您好，纪念品的出处和来历非常重要，直接影响真实性和价值。来源的重要性：一是保真，有明确来源的纪念品可信度高，降低买到假货的风险；二是保值，来源清晰的纪念品在二手市场更受欢迎，出手更容易；三是溢价，有特殊来源（如运动员亲签、现场购买凭证等）的纪念品有额外价值。看来源的方法：一是查看购买凭证，发票、收据等能证明购买渠道；二是查看证书，官方发行的限量证书有编号可查；三是了解流转历史，从谁手里买的、之前怎么来的；四是保留交易记录。建议购买高价纪念品一定追溯来源，不要买来历不明的。您的纪念品有来源记录吗？',
         '来源,出处,保真,保值', '纪念品来源的重要性与查验方法', 83
  UNION ALL SELECT 'art_memorabilia', '限量纪念品编号怎么看？编号小的是不是更值钱？',
         '您好，限量纪念品的编号是限量身份的标识，通常印在产品本身或证书上。编号格式如"001/1000"表示这是1000个限量中的第1号。编号对价值的影响：一是编号大小，编号越小越值钱，001号和最后一个编号有特殊收藏意义，可能比普通编号贵20%到50%；二是限量总数，总量越少越稀缺越值钱；三是编号位置，刻在产品上的比贴纸的更有档次。购买限量纪念品注意：一是确认编号与证书一致；二是确认限量总数与官方信息相符；三是保留限量证书。建议收藏向的优先选小编号的，虽然溢价高但保值增值更好。您的限量纪念品是什么编号？',
         '限量,编号,编号小,价值', '限量纪念品编号的意义与价值', 82
  UNION ALL SELECT 'art_memorabilia', '手里的纪念品想出手，去哪里卖比较好？',
         '您好，纪念品出手渠道有几个选择。渠道对比：一是闲鱼等二手平台，门槛低自己定价，适合中低价纪念品，需要拍照描述和应对砍价；二是专业论坛或收藏群，藏家聚集成交快，适合特定门类的纪念品；三是送拍拍卖行，高价纪念品可能拍出好价，但周期长有佣金；四是邮币卡市场门店，当面交易快速变现，但商家压价；五是评级后出售，贵金属纪念币等评级后更容易卖且价格更好。建议根据纪念品价值选择：低价品走闲鱼或论坛，高价品建议评级后送拍。出手前先了解市场行情合理定价。您的纪念品大概什么价值？',
         '出手,渠道,销售,闲鱼', '纪念品出手渠道对比与建议', 85
  UNION ALL SELECT 'art_memorabilia', '纪念品邮寄怎么包装？怕运输损坏。',
         '您好，纪念品邮寄包装很重要，不同类型包装方式不同。包装建议：一是金属纪念币章，用气泡膜包裹后放入硬质卡纸袋或小纸盒，再装入大纸箱用填充物填满；二是易碎纪念品（如瓷盘、水晶摆件），用气泡膜多层包裹，四角加护角，装入纸箱用泡沫填充；三是签名照片等纸制品，用硬纸板夹板保护，装入硬纸筒或硬纸信封；四是带原装盒的纪念品，先用气泡膜包裹原装盒，再装入外箱。通用建议：箱外标注"易碎品"，选择靠谱快递（建议顺丰），保价运输，卖家打包全程录像，买家先验货再签收。您是买家还是卖家？',
         '邮寄,包装,运输,安全', '纪念品邮寄包装安全指南', 83
  UNION ALL SELECT 'art_memorabilia', '纪念品买回来不满意可以退吗？退换货规则？',
         '您好，纪念品退换货要看具体情况和平台规则。退换货条件：一是如果卖家承诺了七天无理由退货且商品完好，可以申请退货；二是如果收到的实物与描述严重不符（如假货、品相问题未披露、配件缺失），属于描述不符可以申请退款退货；三是如果只是不喜欢但商品没问题且卖家未承诺无理由退货，退货需要和卖家协商。建议购买前确认退换政策，保留聊天记录。收到货先验货再拆封，发现问题不要拆封直接联系卖家。贵金属纪念币等高价品建议当面交易或选择支持验货的卖家。您是遇到退换货问题了吗？',
         '退换货,退款,规则,维权', '纪念品退换货规则与维权指南', 82
  UNION ALL SELECT 'art_memorabilia', '老纪念品有年代了还值钱吗？越老越值钱吗？',
         '您好，老纪念品的价值不能简单说"越老越值钱"，要看多个因素。价值判断因素：一是稀缺性，年代久远且存世量少的纪念品价值高，如清末民初的老纪念章；二是题材意义，有重大历史意义的纪念品价值高，如开国大典纪念品；三是品相，保存完好的老纪念品比品相差的贵很多；四是材质，贵金属材质的老纪念品有材质价值托底；五是市场需求，有藏家群体关注的品类更值钱。需要注意的是，有些老纪念品虽然年代久远但发行量大、题材冷门，价值并不高。建议收藏以题材意义和稀缺性为主要考量，不要唯年代论。您有什么老纪念品？',
         '老纪念品,年代,价值,稀缺性', '老纪念品的价值判断因素', 84
  UNION ALL SELECT 'art_memorabilia', '纪念品投资值得吗？和别的收藏比怎么样？',
         '您好，纪念品投资有其特点，和其他收藏对比分析。优势：一是门槛低，很多纪念品价格亲民，适合新手入门；二是题材丰富，奥运、世博、生肖等题材选择多；三是文化意义，有纪念和情感价值。劣势：一是升值慢，大部分普通纪念品升值有限，不像古董字画那样有大幅增值空间；二是变现难，纪念品市场不如钱币书画成熟，出手周期长；三是受热度影响大，赛事或事件结束后热度下降价格可能回落。建议纪念品以收藏纪念为主，不要纯投资心态。如果投资，聚焦贵金属纪念币和限量品，有材质价值和稀缺性双重支撑。您有想投资的方向吗？',
         '投资,升值,对比,风险', '纪念品投资价值与风险分析', 85
  UNION ALL SELECT 'art_memorabilia', '纪念章的材质怎么看？金银铜怎么区分？',
         '您好，纪念章材质的鉴别很重要，直接影响价值。材质分类和鉴别：一是金质纪念章，标注含金量（如Au.999），重量与标注一致，色泽金黄温润；二是银质纪念章，标注含银量（如Ag.999），重量与标注一致，色泽银白有光泽，时间久了会氧化变暗；三是铜质纪念章，分黄铜和紫铜，黄铜金黄色，紫铜紫红色，重量比金银轻；四是合金镀金镀银，表面镀层内层为合金，重量与纯金属不符。鉴别方法：一是看标注，正规纪念章标有材质和纯度；二是称重量，与标准重量对比；三是看色泽，真金属色泽自然，镀层易褪色。建议贵金属纪念章送评级机构验证。您的纪念章是什么材质？',
         '材质,纪念章,金银,鉴别', '纪念章材质分类与鉴别方法', 84
  UNION ALL SELECT 'art_memorabilia', '纪念品包装盒怎么保存？盒子有破损影响价值吗？',
         '您好，纪念品包装盒的保存很重要，特别是限量发行品。包装盒保存要点：一是防压防潮，包装盒用气泡膜或防潮袋包裹，存放在干燥处，避免重压变形；二是防褪色，避免阳光直射，包装盒印刷容易褪色；三是防磨损，取放时小心，避免刮花印刷面。盒子有破损影响价值：限量品的原装盒是完整收藏的一部分，盒子有破损会贬值10%到20%，因为买家会要求降价以反映品相问题。建议购买时检查盒况，保存时用透明保护套包裹包装盒，既保护又不影响观赏。如果盒子已经破损，可以如实描述后适当降价出售。您的纪念品盒子什么状况？',
         '包装,保存,盒况,价值', '纪念品包装盒保存与价值影响', 80
  UNION ALL SELECT 'art_memorabilia', '明星签名纪念品怎么保存？怕褪色吗？',
         '您好，明星签名纪念品的保存非常重要，签名是最容易受损的部分。保存要点：一是避光，紫外线会使签名墨水褪色，签名照片和衣物要避免阳光直射，建议用防紫外线玻璃框装裱；二是防潮，潮湿会使墨水晕染或发霉，保持存放环境干燥；三是防摩擦，签名表面不要与其他物品摩擦，照片可用塑封或装裱保护，签名衣物建议装裱或密封保存；四是防高温，高温会使墨水变质褪色；五是使用无酸材料，装裱时用无酸卡纸和无酸胶带，避免酸性物质腐蚀签名。建议贵重签名品装裱后展示，用防紫外线玻璃。您的签名纪念品是怎么保存的？',
         '签名,保存,褪色,防潮', '明星签名纪念品保存方法', 83
  UNION ALL SELECT 'art_memorabilia', '纪念品去哪里鉴定？鉴定费一般多少？',
         '您好，纪念品鉴定的渠道和费用因品种而异。鉴定渠道：一是评级机构，贵金属纪念币可送PCGS、NGC等评级，签名可送PSA、JSA等鉴定，费用几十到几百美元不等；二是官方机构，部分纪念品可联系发行方鉴定；三是专业鉴定平台，国内有专业鉴定机构提供有偿鉴定；四是行家掌眼，找有经验的藏友或商家帮忙看。费用参考：国内钱币评级一般50到200元，签名鉴定几百到上千元。选择建议：高价纪念品建议送权威机构鉴定评级，增加保真度和流动性；中低价纪念品找行家掌眼即可。建议先估价再决定是否值得花钱鉴定。您的纪念品大概什么价值？',
         '鉴定,鉴定费,评级,渠道', '纪念品鉴定渠道与费用参考', 82
  UNION ALL SELECT 'art_memorabilia', '纪念品套装比单件值钱吗？全套收藏有什么好处？',
         '您好，纪念品套装通常比单件更值钱，全套收藏有额外价值。套装的优势：一是完整性，全套纪念品比散件更有收藏价值，特别是系列发行品；二是稀缺性，完整保存全套的比单件少，物以稀为贵；三是溢价，全套出售时比单件分别出售总价高10%到30%；四是故事性，全套有完整的收藏故事，对买家更有吸引力。全套收藏的好处：一是系统性强，能完整了解一个主题或系列；二是展示效果好，全套展示比单件更有气势；三是保值增值好，全套的市场认可度高。建议收藏时尽量保持全套完整性，不要拆散出售，保留原装包装和证书。您的纪念品是全套吗？',
         '套装,全套,单件,收藏价值', '纪念品套装的价值与收藏好处', 83
  UNION ALL SELECT 'art_memorabilia', '纪念品怎么清洁保养？能用水洗吗？',
         '您好，纪念品清洁保养要非常谨慎，不同材质保养方法不同。清洁建议：一是金属纪念币章，不要用水洗，用软毛刷或超细纤维布轻擦即可，氧化变暗是正常现象不要强行除锈；二是签名照片，不要清洁签名面，照片背面用软布轻擦；三是水晶瓷盘等摆件，用干软布擦拭，不要用化学清洁剂；四是毛绒吉祥物等，用干洗或局部擦拭，不要水洗以免变形褪色。通用原则：一是能不清洁就不清洁，保持原样最安全；二是不要用化学清洁剂，会损伤表面；三是不要用超声波清洗，会破坏品相；四是贵金属纪念币不要清洗，清洗会降低评级分。建议清洁前咨询专业人士。您的纪念品是什么材质？',
         '清洁,保养,水洗,材质', '纪念品清洁保养的安全原则', 81
  UNION ALL SELECT 'art_memorabilia', '纪念品回购靠谱吗？哪里可以回购？',
         '您好，纪念品回购渠道有几个选择。回购渠道：一是银行回购，部分银行回购本行发行的贵金属纪念币，价格按贵金属市价折算，最靠谱但价格低；二是邮币卡市场，商家收购纪念品，当面交易快速变现，但商家压价严重；三是二手平台出售，闲鱼等平台自己定价出售，价格可能更高但需要时间；四是评级后出售，评级后的纪念品更容易卖且价格更好。回购价格参考：贵金属纪念币回购价通常按贵金属市价加少量溢价，远低于发行价和市场价。建议如果不急用钱，在二手平台自己出售比回购更划算。如果急用钱，银行回购最安全。您的纪念品想回购还是出售？',
         '回购,渠道,变现,价格', '纪念品回购渠道与价格参考', 82
  UNION ALL SELECT 'art_memorabilia', '现在纪念品市场行情怎么样？值得收藏吗？',
         '您好，纪念品市场行情给您客观分析。行情趋势：一是贵金属纪念品随金价银价波动，近年贵金属价格上涨带动金银纪念币升值；二是限量纪念品分化明显，热门题材限量品保值增值，普通发行品贬值；三是签名纪念品受名人热度影响，当红明星签名品价格高，过气明星签名品回落；四是赛事纪念品受赛事周期影响，赛事期间热度高赛后回落。值得收藏吗：纪念品的收藏价值不仅在投资升值，更在于文化纪念意义。建议以收藏心态入手，选择有纪念意义的题材，保留证书和包装。如果投资聚焦贵金属纪念币和热门限量品。您有感兴趣的方向吗？',
         '行情,市场,收藏,投资', '纪念品市场行情与收藏建议', 84
  UNION ALL SELECT 'art_memorabilia', '纪念品收藏新手怎么入门？有什么建议？',
         '您好，纪念品收藏入门给几点建议：一是从自己感兴趣的题材入手，收藏有情感连接的纪念品更有乐趣，如自己喜欢的赛事、明星或主题；二是从官方渠道购买，确保正品，保留证书和发票；三是先学后买，了解纪念品的发行信息、市场行情和鉴别方法，不要盲目出手；四是从低价品入门，用低成本积累经验，逐步向高价品进阶；五是保持品相，保留原装包装和证书，品相对于纪念品价值非常重要；六是量力而行，用闲钱收藏不要影响生活；七是加入收藏圈交流学习，少走弯路。收藏最重要的是享受过程，不要抱着暴富心态。您对哪个方向的纪念品感兴趣？',
         '入门,新手,收藏建议,学习', '纪念品收藏新手入门指南', 87
  UNION ALL SELECT 'art_memorabilia', '纪念品怎么辨伪？有没有快速判断的方法？',
         '您好，纪念品辨伪有几个快速判断方法。通用辨伪要点：一看工艺，正品工艺精细做工规整，假货做工粗糙有瑕疵；二看材质，正品材质与标注一致有特定重量和色泽，假货材质廉价重量不对；三看包装证书，正品有官方原装包装和证书，印刷精美有防伪标识，假货包装粗糙证书造假；四看价格，远低于市场价的大概率是假货；五看来源，官方渠道或信誉好的卖家可信度高，来路不明的风险大。不同品种的专项辨伪：纪念币看重量和工艺，签名品对比真迹样本，限量品核对编号和证书。建议新手从官方渠道购买，减少买到假货的风险。您有具体的纪念品想鉴定吗？',
         '辨伪,真假辨别,快速判断,鉴别', '纪念品快速辨伪方法汇总', 85
  UNION ALL SELECT 'art_memorabilia', '纪念品有磕碰划痕影响价值吗？怎么处理？',
         '您好，纪念品有磕碰划痕确实影响价值，影响程度取决于几个因素。影响评估：一是磕碰位置，正面比背面影响大，关键图案部位比边缘影响大；二是磕碰程度，轻微划痕影响小（贬值5%到10%），明显磕碰坑或变形影响大（贬值20%到40%）；三是纪念品本身价值，高价品的瑕疵影响更大；四是品种类型，贵金属纪念币的瑕疵影响评级分，签名品的签名完好最重要。处理建议：一是不要自行修复，不当修复会加重损伤；二是金属纪念币的轻微划痕无法修复，保持原样；三是摆件类可用专业修复师修补；四是购买时要求卖家拍清瑕疵部位图，评估是否可接受。您的纪念品磕碰严重吗？',
         '磕碰,划痕,品相,价值评估', '纪念品磕碰划痕的价值影响与处理', 80
  UNION ALL SELECT 'art_memorabilia', '纪念品放久了氧化变色正常吗？影响价值吗？',
         '您好，纪念品氧化变色是金属材质的自然现象，是否影响价值要看情况。氧化分析：一是银质纪念品氧化变暗发黑是正常现象，称为"包浆"，自然均匀的氧化不影响价值，甚至有岁月感，但局部严重氧化影响美观；二是铜质纪念品氧化产生绿锈或红斑，自然氧化有古朴感，但有害锈需要处理；三是金质纪念品化学性质稳定不易氧化，氧化极少。对价值的影响：自然均匀的氧化不影响价值，反而是年代的证明；不均匀的氧化或有害锈影响品相和价值。处理建议：一是不要自行清洗除锈，清洗会降低价值；二是保持干燥环境减缓氧化；三是有害锈找专业人士处理。建议贵金属纪念品用密封盒或评级封装保护。您的纪念品氧化严重吗？',
         '氧化,变色,包浆,品相', '纪念品氧化变色的原因与价值影响', 83
  UNION ALL SELECT 'art_memorabilia', '买的纪念品和图片不一样怎么办？能投诉吗？',
         '您好，收到的纪念品与图片不符是比较常见的纠纷。处理步骤：一是保留证据，收到货后先拍照录像记录实物状态，与商品页面的图片描述对比，截屏保存商品描述和聊天记录；二是联系卖家，先与卖家沟通说明问题，看卖家是否愿意退换或补偿；三是申请退款，如果卖家不配合且实物与描述严重不符，可以在闲鱼平台申请退款退货，上传证据照片；四是平台介入，如果卖家拒绝退款可以申请平台客服介入处理；五是评价提醒，交易完成后如实评价提醒其他买家。建议购买时选择支持验货的卖家，收到货先验货再确认收货。您收到的纪念品和图片差多少？',
         '图片不符,投诉,退款,维权', '纪念品描述不符的维权流程', 84
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;